export const ba_pair_disjoint_bench = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> by_inverse_a_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

// Disjoint pair-sum kernel — each thread reduces 2*S input points to S
// disjoint pair sums R_k = P_{2k} + P_{2k+1} (k in 0..S) using the
// same forward-prefix / single-inversion / backward-peel batched-
// inverse pattern as ba_rev_packed_carry, but with NO load-carry
// overlap. Every kernel-output is a distinct pair sum suitable as
// input to the next level of a pair-tree reduction — closes the 50%
// kernel-efficiency loss inherent in the streaming chain kernel.
//
// Storage: SoA-packed 8x u32 per field (PG=2 vec4/elem).
//   Input planes (binding 0):
//     plane 0 (P.x): PG * N_in vec4, N_in = 2*S*T
//     plane 1 (P.y): PG * N_in vec4
//   Output planes (binding 2):
//     plane 0 (R.x): PG * N_out vec4, N_out = S*T
//     plane 1 (R.y): PG * N_out vec4
//
// Thread t reads P_i = (inp[plane c at index t + i*T] : c in {0,1}) for
// i in 0..2S (strided => coalesced). Pair k pairs adjacent strided
// slots: (P_{2k}, P_{2k+1}). Output R_k is written at index t + k*T in
// plane c of outp (also strided, coalesced).
//
// dx values dx_k = P_{2k+1}.x - P_{2k}.x are all mutually independent
// (no shared inputs across k), so the standard Montgomery batched
// inverse trick applies as-is: ONE fr_inv_by_a per chunk of S.
//
// Same Karatsuba+Yuval montmul and BY-safegcd fr_inv_by_a as the
// production stack and the chain kernel.

const S: u32 = {{ s }}u;
const PG: u32 = 2u;

@group(0) @binding(0) var<storage, read>       inp:    array<vec4<u32>>;
@group(0) @binding(1) var<storage, read>       unused: array<vec4<u32>>;
@group(0) @binding(2) var<storage, read_write> outp:   array<vec4<u32>>;
@group(0) @binding(3) var<uniform>             params: vec4<u32>;

fn load_in(plane: u32, t: u32, i: u32, T: u32, N_in: u32) -> BigInt {
    let plane_base = plane * PG * N_in;
    let base = plane_base + PG * (t + i * T);
    let q0 = inp[base + 0u];
    let q1 = inp[base + 1u];
    var w: array<u32, 8>;
    w[0] = q0.x; w[1] = q0.y; w[2] = q0.z; w[3] = q0.w;
    w[4] = q1.x; w[5] = q1.y; w[6] = q1.z; w[7] = q1.w;
    return unpack256_to_limbs(w);
}

fn store_out(plane: u32, t: u32, k: u32, T: u32, N_out: u32, val: ptr<function, BigInt>) {
    let plane_base = plane * PG * N_out;
    let base = plane_base + PG * (t + k * T);
    let w = pack_limbs_to_256(val);
    outp[base + 0u] = vec4<u32>(w[0], w[1], w[2], w[3]);
    outp[base + 1u] = vec4<u32>(w[4], w[5], w[6], w[7]);
}

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let N_in = params.x;
    let T = params.y;
    let N_out = N_in / 2u;

    let t = gid.x;
    if (t >= T) { return; }

    // Forward: prefix product of S independent dx values.
    var pref: array<BigInt, {{ s }}>;
    var acc: BigInt = get_r();
    for (var k: u32 = 0u; k < S; k = k + 1u) {
        var p_lx: BigInt = load_in(0u, t, 2u * k + 0u, T, N_in);
        var p_rx: BigInt = load_in(0u, t, 2u * k + 1u, T, N_in);
        var dx: BigInt = fr_sub(&p_rx, &p_lx);
        if (k == 0u) {
            acc = dx;
        } else {
            acc = montgomery_product(&acc, &dx);
        }
        pref[k] = acc;
    }

    // One BY-safegcd inversion amortised over all S pair sums.
    var inv: BigInt = fr_inv_by_a(acc);

    // Backward peel: emit S disjoint pair sums.
    for (var jj: u32 = 0u; jj < S; jj = jj + 1u) {
        let k = S - 1u - jj;

        var p_lx: BigInt = load_in(0u, t, 2u * k + 0u, T, N_in);
        var p_ly: BigInt = load_in(1u, t, 2u * k + 0u, T, N_in);
        var p_rx: BigInt = load_in(0u, t, 2u * k + 1u, T, N_in);
        var p_ry: BigInt = load_in(1u, t, 2u * k + 1u, T, N_in);

        var inv_dx: BigInt;
        if (k == 0u) {
            inv_dx = inv;
        } else {
            var pp = pref[k - 1u];
            inv_dx = montgomery_product(&inv, &pp);
        }

        var lambda: BigInt = fr_sub(&p_ry, &p_ly);
        lambda = montgomery_product(&lambda, &inv_dx);
        var r_x: BigInt = montgomery_product(&lambda, &lambda);
        r_x = fr_sub(&r_x, &p_lx);
        r_x = fr_sub(&r_x, &p_rx);
        var r_y: BigInt = fr_sub(&p_lx, &r_x);
        r_y = montgomery_product(&lambda, &r_y);
        r_y = fr_sub(&r_y, &p_ly);

        store_out(0u, t, k, T, N_out, &r_x);
        store_out(1u, t, k, T, N_out, &r_y);

        // Advance inv to 1/pref[k-1] for the next (smaller) iteration.
        if (k > 0u) {
            var dx_back: BigInt = fr_sub(&p_rx, &p_lx);
            inv = montgomery_product(&inv, &dx_back);
        }
    }

    {{{ recompile }}}
}
`;

export const ba_pair_disjoint_tree_bench = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> by_inverse_a_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

// Disjoint pair-sum kernel — tree variant. Each thread reduces 2*S
// input points to S disjoint pair sums R_k = P_{2k} + P_{2k+1}, using
// one batched fr_inv_by_a per chunk of S.
//
// vs ba_pair_disjoint_bench: writes outputs in the LAYOUT THE NEXT
// PAIR-TREE LEVEL EXPECTS AS INPUT, eliminating the need for an
// intervening marshal/reshuffle dispatch between levels.
//
// Strided read at level k: thread t reads input slot i at flat
//   in_pos(t, i) = t + i * T_curr            (i in [0, 2*S))
//
// Strided write that next level reads correctly: thread t writes
// output slot i at flat
//   out_pos(t, i) = (t >> 1) + (i + S * (t & 1)) * (T_curr >> 1)
//
// Derivation: next level uses T_next = T_curr / 2 threads. For
// next-level thread t_n = t >> 1 to read its 2*S inputs in the right
// pair-tree order (first S from prev thread (2*t_n), next S from prev
// thread (2*t_n + 1)), the current level's output slots interleave:
// odd-t writes go into the upper-S input slots of the next level's
// thread (t >> 1), even-t into the lower-S slots.
//
// This preserves the per-bucket-pair invariant: at every level, the
// disjoint pairs (P_{2j}, P_{2j+1}) belong to the same bucket pool,
// so the lean affine formula is always combining points whose dx is
// well-defined.
//
// PARAMS:
//   params.x = N_in  = 2 * S * T_curr  (total input elements per plane)
//   params.y = T_curr
//
// LAYOUT (both input and output buffers):
//   2 planes (P.x, P.y), PG=2 vec4 per element.
//   Plane p flat index for vec4 access: p * PG * N_buf + PG * e + {0,1}
//   where N_buf is the elements-per-plane for that buffer.
//   Input buffer's N_buf = 2 * S * T_curr (= N_in).
//   Output buffer's N_buf = S * T_curr (= N_in / 2).

const S: u32 = {{ s }}u;
const PG: u32 = 2u;

@group(0) @binding(0) var<storage, read>       inp:    array<vec4<u32>>;
@group(0) @binding(1) var<storage, read>       unused: array<vec4<u32>>;
@group(0) @binding(2) var<storage, read_write> outp:   array<vec4<u32>>;
@group(0) @binding(3) var<uniform>             params: vec4<u32>;

fn load_in(plane: u32, t: u32, i: u32, T: u32, N_in: u32) -> BigInt {
    let plane_base = plane * PG * N_in;
    let base = plane_base + PG * (t + i * T);
    let q0 = inp[base + 0u];
    let q1 = inp[base + 1u];
    var w: array<u32, 8>;
    w[0] = q0.x; w[1] = q0.y; w[2] = q0.z; w[3] = q0.w;
    w[4] = q1.x; w[5] = q1.y; w[6] = q1.z; w[7] = q1.w;
    return unpack256_to_limbs(w);
}

fn store_out_tree(plane: u32, t: u32, k: u32, T_curr: u32, N_out: u32, val: ptr<function, BigInt>) {
    // Tree write: out_pos(t, k) = (t >> 1) + (k + S * (t & 1)) * (T_curr >> 1)
    // Lands in next-level strided read at index (t >> 1) with slot
    // (k + S * (t & 1)).
    let t_next = t >> 1u;
    let slot_in_next = k + S * (t & 1u);
    let T_next = T_curr >> 1u;
    let plane_base = plane * PG * N_out;
    let elem = t_next + slot_in_next * T_next;
    let base = plane_base + PG * elem;
    let w = pack_limbs_to_256(val);
    outp[base + 0u] = vec4<u32>(w[0], w[1], w[2], w[3]);
    outp[base + 1u] = vec4<u32>(w[4], w[5], w[6], w[7]);
}

fn store_out_simple(plane: u32, t: u32, k: u32, T_curr: u32, N_out: u32, val: ptr<function, BigInt>) {
    // Final-level simple strided write: out_pos(t, k) = t + k * T_curr.
    // Used when there is no next pair-tree level (T_curr == 1 thread, or
    // the host indicates this is the last reduction step).
    let plane_base = plane * PG * N_out;
    let elem = t + k * T_curr;
    let base = plane_base + PG * elem;
    let w = pack_limbs_to_256(val);
    outp[base + 0u] = vec4<u32>(w[0], w[1], w[2], w[3]);
    outp[base + 1u] = vec4<u32>(w[4], w[5], w[6], w[7]);
}

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let N_in = params.x;
    let T_curr = params.y;
    let final_flag = params.z;   // non-zero => use simple strided write
    let N_out = N_in / 2u;

    let t = gid.x;
    if (t >= T_curr) { return; }

    var pref: array<BigInt, {{ s }}>;
    var acc: BigInt = get_r();
    for (var k: u32 = 0u; k < S; k = k + 1u) {
        var p_lx: BigInt = load_in(0u, t, 2u * k + 0u, T_curr, N_in);
        var p_rx: BigInt = load_in(0u, t, 2u * k + 1u, T_curr, N_in);
        var dx: BigInt = fr_sub(&p_rx, &p_lx);
        if (k == 0u) {
            acc = dx;
        } else {
            acc = montgomery_product(&acc, &dx);
        }
        pref[k] = acc;
    }

    var inv: BigInt = fr_inv_by_a(acc);

    for (var jj: u32 = 0u; jj < S; jj = jj + 1u) {
        let k = S - 1u - jj;

        var p_lx: BigInt = load_in(0u, t, 2u * k + 0u, T_curr, N_in);
        var p_ly: BigInt = load_in(1u, t, 2u * k + 0u, T_curr, N_in);
        var p_rx: BigInt = load_in(0u, t, 2u * k + 1u, T_curr, N_in);
        var p_ry: BigInt = load_in(1u, t, 2u * k + 1u, T_curr, N_in);

        var inv_dx: BigInt;
        if (k == 0u) {
            inv_dx = inv;
        } else {
            var pp = pref[k - 1u];
            inv_dx = montgomery_product(&inv, &pp);
        }

        var lambda: BigInt = fr_sub(&p_ry, &p_ly);
        lambda = montgomery_product(&lambda, &inv_dx);
        var r_x: BigInt = montgomery_product(&lambda, &lambda);
        r_x = fr_sub(&r_x, &p_lx);
        r_x = fr_sub(&r_x, &p_rx);
        var r_y: BigInt = fr_sub(&p_lx, &r_x);
        r_y = montgomery_product(&lambda, &r_y);
        r_y = fr_sub(&r_y, &p_ly);

        if (final_flag != 0u) {
            store_out_simple(0u, t, k, T_curr, N_out, &r_x);
            store_out_simple(1u, t, k, T_curr, N_out, &r_y);
        } else {
            store_out_tree(0u, t, k, T_curr, N_out, &r_x);
            store_out_tree(1u, t, k, T_curr, N_out, &r_y);
        }

        if (k > 0u) {
            var dx_back: BigInt = fr_sub(&p_rx, &p_lx);
            inv = montgomery_product(&inv, &dx_back);
        }
    }

    {{{ recompile }}}
}
`;

export const ba_planner_bench = `{{> structs }}

// GPU-side bin-packing planner for the v3 MSM bucket-accumulate
// pipeline. One thread per bucket; uses atomicAdd to reserve global
// per-pair slots in chunk_plan / scatter_plan and per-carry slots in
// carry_plan, then writes that bucket's entries.
//
// Inputs (per current level):
//   counts:  array<u32>     per-bucket active count
//   offsets: array<u32>     per-bucket starting index in active_sums_old
//
// Outputs (filled in by this kernel for the current level):
//   chunk_plan:   array<u32>          2 u32 per (chunk_id, slot) — pair operand indices
//   scatter_plan: array<u32>          1 u32 per (chunk_id, slot) — destination in active_sums_new
//   carry_plan:   array<u32>          2 u32 per carry slot — (src in old, dst in new)
//   totals:       array<atomic<u32>>  [0]=total pairs, [1]=total carries, [2]=total new actives
//   new_counts:   array<u32>          per-bucket new active count (for next level)
//   new_offsets:  array<u32>          per-bucket new offset in active_sums_new (for next level)
//
// Convention: discard slot = M_new - 1 (the highest index in
// active_sums_new). Pad pair source indices = (pad_l_idx, pad_r_idx)
// supplied via params. All non-real chunk_plan / scatter_plan slots
// must be pre-padded to (pad_l_idx, pad_r_idx) and discard_idx by the
// host before each planner dispatch.
//
// params.x = B (bucket count)
// params.y = S (chunk size, slots per chunk)
//   (pad_l_idx / pad_r_idx / discard_idx live in the pre-padded
//    arrays, not in params)

const S: u32 = {{ s }}u;

@group(0) @binding(0) var<storage, read>             counts:       array<u32>;
@group(0) @binding(1) var<storage, read>             offsets:      array<u32>;
@group(0) @binding(2) var<storage, read_write>       chunk_plan:   array<u32>;
@group(0) @binding(3) var<storage, read_write>       scatter_plan: array<u32>;
@group(0) @binding(4) var<storage, read_write>       carry_plan:   array<u32>;
@group(0) @binding(5) var<storage, read_write>       totals:       array<atomic<u32>>;
@group(0) @binding(6) var<storage, read_write>       new_counts:   array<u32>;
@group(0) @binding(7) var<storage, read_write>       new_offsets:  array<u32>;
@group(0) @binding(8) var<uniform>                   params:       vec4<u32>;

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let B = params.x;
    let b = gid.x;
    if (b >= B) { return; }

    let n = counts[b];
    let pair_count = n / 2u;
    let carry_flag = n & 1u;
    let nc = pair_count + carry_flag;
    new_counts[b] = nc;

    // Atomic offset reservation. Each bucket gets a unique non-overlapping
    // range in the global arrays. Atomic order is non-deterministic but
    // that's fine: bucket b records its assigned offsets and uses them
    // consistently for its own chunk_plan / scatter_plan / new_offsets
    // writes. Different buckets land in different ranges by construction.
    let my_pair_off = atomicAdd(&totals[0u], pair_count);
    let my_carry_off = atomicAdd(&totals[1u], carry_flag);
    let my_new_off = atomicAdd(&totals[2u], nc);
    new_offsets[b] = my_new_off;

    let bucket_base = offsets[b];

    // Write this bucket's pair entries into chunk_plan / scatter_plan.
    // Loop bounded by pair_count (variable per bucket; typically ~16
    // for Poisson(λ=32)). The TAIL_CAP-style compile-time bound used
    // by ba_tail_reduce isn't strictly needed here since this kernel
    // doesn't do field arithmetic; the loop is plain integer writes.
    // We still bound it by a compile-time constant for WGSL static
    // analysis purposes.
    let PAIR_CAP: u32 = {{ pair_cap }}u;
    for (var j: u32 = 0u; j < PAIR_CAP; j = j + 1u) {
        if (j >= pair_count) { break; }
        let global_slot = my_pair_off + j;
        let chunk_id = global_slot / S;
        let slot_in_chunk = global_slot % S;
        let cp_base = 2u * (chunk_id * S + slot_in_chunk);
        chunk_plan[cp_base + 0u] = bucket_base + 2u * j;
        chunk_plan[cp_base + 1u] = bucket_base + 2u * j + 1u;
        scatter_plan[chunk_id * S + slot_in_chunk] = my_new_off + j;
    }

    if (carry_flag != 0u) {
        let cs = my_carry_off;
        carry_plan[2u * cs + 0u] = bucket_base + n - 1u;
        carry_plan[2u * cs + 1u] = my_new_off + pair_count;
    }

    {{{ recompile }}}
}
`;

export const ba_planner_v2_bench = `{{> structs }}

// Bin-packing planner for the MSM bucket-accumulate pair-tree —
// one workgroup per Pippenger window.
//
// The MSM splits each scalar into NUM_WINDOWS windows of c bits; each
// window is an independent bucket-method sub-problem of BW = 2^(c-1)
// buckets. This kernel dispatches one workgroup per window: workgroup
// w plans window w entirely on its own, with no cross-workgroup
// communication (the windows never interact).
//
// Within a workgroup the algorithm is the single-window scan+scatter
// planner. One workgroup of TPB threads covers BW buckets; thread tid
// owns the contiguous slice [tid*PER_THREAD, (tid+1)*PER_THREAD).
//
// Finalize-and-drop: a bucket whose count is exactly 1 is already
// reduced — its single element IS the bucket sum. Such a bucket emits
// no pair and no carry, and gets new_count = 0, so it drops out of
// every deeper level (the offset scan compacts around it for free).
// The one-time copy of its element to the bucket-result buffer is left
// to a downstream kernel, which finds finalized buckets directly via
// counts[b] == 1 — the planner emits nothing extra for it. This keeps
// the deep tree levels (reached only when some bucket is unusually
// large) from carry-copying every already-finished bucket forever.
//
// Phase A — Per-thread local tally
//   For each of its PER_THREAD buckets compute (pair_count, carry_flag,
//   new_count) and accumulate per-thread totals. The per-bucket triples
//   are NOT cached (PER_THREAD is large for production windows); Phase
//   C recomputes them.
//
// Phase B — Workgroup-wide Hillis-Steele scan (3 in parallel)
//   Scan the per-thread totals for pair / carry / new across the TPB
//   threads in shared memory. Each thread gets the exclusive prefix at
//   the start of its slice (= base offset for its first bucket).
//
// Phase C — Per-thread scatter
//   Walk the slice again, recomputing (pc, cf, nc) per bucket, and
//   write the chunk_plan / scatter_plan / carry_plan entries plus
//   new_counts / new_offsets, seeded by the Phase B prefix.
//
// Phase D — Window totals + level-wide indirect-dispatch args.
//
// Per-window output layout: window w's chunk_plan / scatter_plan /
// carry_plan occupy fixed-size regions of CHUNKS_PER_WINDOW chunks and
// CARRIES_PER_WINDOW carries (params.x / params.y — the host sizes them
// to the largest window). new_counts / new_offsets are indexed by
// global bucket id.
//
// plan_meta buffer layout (u32):
//   [0 .. 3*NUM_WINDOWS)        per-window totals: 3*w + {pairs,carries,new}
//   [3*NUM_WINDOWS   .. +3)     indirect-dispatch args for the chunk
//                               kernels: (workgroup_count, 1, 1)
//   [3*NUM_WINDOWS+3 .. +3)     indirect-dispatch args for the carry
//                               kernel:  (workgroup_count, 1, 1)
//   The workgroup counts assume a consumer of workgroup size WGI
//   walking the full NUM_WINDOWS * stride layout. They right-size per
//   level for free: the host shrinks CHUNKS/CARRIES_PER_WINDOW as the
//   pair count falls, so an all-finished level yields a (0,1,1) no-op.
//
// One dispatch of NUM_WINDOWS workgroups, no atomics, no host sync.
// Each window's BW buckets must fit one workgroup, so BW must be a
// positive multiple of TPB (PER_THREAD = BW / TPB).
//
// Compile-time constants:
//   TPB          : workgroup size (e.g. 256)
//   BW           : buckets per window = 2^(c-1)
//   PER_THREAD   : buckets per thread = BW / TPB
//   NUM_WINDOWS  : ceil(num_bits / c)
//   PAIR_CAP     : per-bucket pair-count bound (Poisson(λ=32) tail is
//                  ~30; 64 is safe)
//   S            : chunk size in pairs (e.g. 16)
//
// Runtime (params uniform):
//   params.x = CHUNKS_PER_WINDOW    per-window output stride, in chunks
//   params.y = CARRIES_PER_WINDOW   per-window output stride, in carries
//   params.z = WGI                  consumer workgroup size, used to
//                                   size the indirect-dispatch args
//   params.w = WSTRIDE              active_sums slots per window; added
//                                   to new_offsets / scatter_plan /
//                                   carry destinations so they index
//                                   the global active_sums. 0 keeps the
//                                   window-local behaviour (back-compat).

const TPB: u32 = {{ workgroup_size }}u;
const BW: u32 = {{ buckets_per_window }}u;
const PER_THREAD: u32 = {{ per_thread }}u;
const NUM_WINDOWS: u32 = {{ num_windows }}u;
const PAIR_CAP: u32 = {{ pair_cap }}u;
const S: u32 = {{ s }}u;

@group(0) @binding(0) var<storage, read>       counts:       array<u32>;
@group(0) @binding(1) var<storage, read>       offsets:      array<u32>;
@group(0) @binding(2) var<storage, read_write> chunk_plan:   array<u32>;
@group(0) @binding(3) var<storage, read_write> scatter_plan: array<u32>;
@group(0) @binding(4) var<storage, read_write> carry_plan:   array<u32>;
@group(0) @binding(5) var<storage, read_write> new_counts:   array<u32>;
@group(0) @binding(6) var<storage, read_write> new_offsets:  array<u32>;
@group(0) @binding(7) var<storage, read_write> plan_meta:    array<u32>;
@group(0) @binding(8) var<uniform>             params:       vec4<u32>;

// Workgroup-shared running prefixes for the 3 scans.
var<workgroup> pair_scan:  array<u32, {{ workgroup_size }}>;
var<workgroup> carry_scan: array<u32, {{ workgroup_size }}>;
var<workgroup> new_scan:   array<u32, {{ workgroup_size }}>;

fn ceil_div(a: u32, b: u32) -> u32 {
    return (a + b - 1u) / b;
}

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let tid = lid.x;
    let w = wid.x;                       // window index = workgroup index
    if (w >= NUM_WINDOWS) { return; }     // w is uniform across the workgroup

    let chunks_per_window  = params.x;
    let carries_per_window = params.y;
    let wstride            = params.w;   // active_sums slots per window

    let window_bucket_base = w * BW;
    let window_chunk_base  = w * chunks_per_window;
    let window_carry_base  = w * carries_per_window;

    // Phase A: per-thread tally over this thread's PER_THREAD buckets.
    var sum_p: u32 = 0u;
    var sum_c: u32 = 0u;
    var sum_n: u32 = 0u;
    for (var k: u32 = 0u; k < PER_THREAD; k = k + 1u) {
        let b_local = tid * PER_THREAD + k;
        if (b_local < BW) {
            let n = counts[window_bucket_base + b_local];
            let pc = n / 2u;
            // count == 1: bucket is already reduced -> finalize-and-drop
            // (no carry, no next-level slot). count 0 also yields cf = 0.
            let cf = select(n & 1u, 0u, n == 1u);
            sum_p += pc;
            sum_c += cf;
            sum_n += pc + cf;
        }
    }

    // Phase B: workgroup-wide Hillis-Steele inclusive scan over the
    // per-thread totals (3 scans interleaved).
    pair_scan[tid] = sum_p;
    carry_scan[tid] = sum_c;
    new_scan[tid] = sum_n;
    workgroupBarrier();
    for (var stride: u32 = 1u; stride < TPB; stride = stride * 2u) {
        var add_p: u32 = 0u;
        var add_c: u32 = 0u;
        var add_n: u32 = 0u;
        if (tid >= stride) {
            add_p = pair_scan[tid - stride];
            add_c = carry_scan[tid - stride];
            add_n = new_scan[tid - stride];
        }
        workgroupBarrier();
        if (tid >= stride) {
            pair_scan[tid] = pair_scan[tid] + add_p;
            carry_scan[tid] = carry_scan[tid] + add_c;
            new_scan[tid] = new_scan[tid] + add_n;
        }
        workgroupBarrier();
    }
    // pair_scan[tid] is now the inclusive prefix. Exclusive base = inclusive - own.
    var local_pair_off: u32 = pair_scan[tid] - sum_p;
    var local_carry_off: u32 = carry_scan[tid] - sum_c;
    var local_new_off: u32 = new_scan[tid] - sum_n;

    // Phase D: last thread writes this window's totals.
    if (tid == TPB - 1u) {
        plan_meta[3u * w + 0u] = pair_scan[tid];
        plan_meta[3u * w + 1u] = carry_scan[tid];
        plan_meta[3u * w + 2u] = new_scan[tid];
    }
    // One designated thread writes the level-wide indirect-dispatch
    // args (uniform across windows: function of strides + WGI only).
    if (w == 0u && tid == 0u) {
        let wgi = max(params.z, 1u);
        let d = 3u * NUM_WINDOWS;
        plan_meta[d + 0u] = ceil_div(NUM_WINDOWS * chunks_per_window, wgi);
        plan_meta[d + 1u] = 1u;
        plan_meta[d + 2u] = 1u;
        plan_meta[d + 3u] = ceil_div(NUM_WINDOWS * carries_per_window, wgi);
        plan_meta[d + 4u] = 1u;
        plan_meta[d + 5u] = 1u;
    }

    // Phase C: per-thread scatter.
    for (var k: u32 = 0u; k < PER_THREAD; k = k + 1u) {
        let b_local = tid * PER_THREAD + k;
        if (b_local >= BW) { break; }
        let b = window_bucket_base + b_local;

        let n = counts[b];
        let pc = n / 2u;
        let cf = select(n & 1u, 0u, n == 1u);   // count == 1 -> finalize-and-drop
        let nc = pc + cf;
        new_counts[b] = nc;
        new_offsets[b] = w * wstride + local_new_off;

        let bucket_base = offsets[b];

        // Pair entries: bounded loop, break at pc.
        for (var j: u32 = 0u; j < PAIR_CAP; j = j + 1u) {
            if (j >= pc) { break; }
            let slot_in_window = local_pair_off + j;
            let global_chunk = window_chunk_base + slot_in_window / S;
            let slot_in_chunk = slot_in_window % S;
            let flat_slot = global_chunk * S + slot_in_chunk;
            chunk_plan[2u * flat_slot + 0u] = bucket_base + 2u * j;
            chunk_plan[2u * flat_slot + 1u] = bucket_base + 2u * j + 1u;
            scatter_plan[flat_slot] = w * wstride + local_new_off + j;
        }

        // Carry entry (odd count > 1; count == 1 finalizes instead).
        if (cf != 0u) {
            let cs = window_carry_base + local_carry_off;
            carry_plan[2u * cs + 0u] = bucket_base + n - 1u;
            carry_plan[2u * cs + 1u] = w * wstride + local_new_off + pc;
        }

        local_pair_off += pc;
        local_carry_off += cf;
        local_new_off += nc;
    }

    {{{ recompile }}}
}
`;

export const ba_rev_packed_carry_bench = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> by_inverse_a_funcs }}

// MSM-integrated bucket-accumulate batch-affine kernel — packed 8x u32
// storage + decoupled (full-ILP) pack/unpack + reversed direction +
// resident-accumulator load-carry. Drives the canonical
// ba_rev_packed_carry benchmark that reached ~22 ns/pair on M2 / Chrome
// 148 (-55% vs the production batch-affine kernel).
//
// Math is byte-identical to ba_msm_bucket_bench: forward running
// prefix-product of the S dx values in a private array<BigInt,S>, ONE
// fr_inv_by_a per chunk of S, backward peel with the lean affine
// formula (dx recomputed free in the backward pass), resident
// accumulator A.x kept in registers across the whole chunk (load-carry:
// A_{i+1} := P_i so the forward and backward passes share one global
// P_i.x load per iteration). Same Karatsuba+Yuval montmul and BY-safegcd
// fr_inv_by_a as the production stack.
//
// The single structural change from ba_msm_bucket_bench:
//   global storage is the packed 254-bit value stored as 8x u32
//   (32 bytes/elem == 2x vec4<u32>), not the 20x 13-bit-limb BigInt
//   (80 bytes/elem == 5x vec4<u32>). Unpack into 20x13-bit limbs only
//   in-register at load and repack on store. The pack/unpack is the
//   decoupled full-ILP straight-line form (injected below as
//   unpack256_to_limbs / pack_limbs_to_256): 20 mutually-independent
//   compile-time-constant-indexed limb extractions, zero loop-carried
//   bit-cursor dependency chain. This cuts global traffic 2.5x (the
//   dominant cost in the memory-bound batch-affine kernel) at a
//   sub-cycle in-register cost.
//
// LAYOUT: packed elem = 2 vec4<u32>; for each of the 4 input planes
// (A.x, A.y, P.x, P.y) and 2 output planes (R.x, R.y), plane c holds
// N elements at indices c*2*N + 2*e + {0,1}. params.x = N (total
// point-adds), params.y = T (thread count = N/S).
//
// Thread t streams points e = t + i*T for i in 0..S (strided => fully
// coalesced across the apply phase). The "left" operand of add i is the
// running accumulator A_i; A_0 is the per-thread seed (plane 0/1 at
// e=t), A_{i+1} := P_i (load-carry; same global address as forward
// pass's P_i load, no extra global traffic).

const S: u32 = {{ s }}u;
const PG: u32 = 2u; // 8 u32 packed limbs / 4 = 2 vec4 groups

@group(0) @binding(0) var<storage, read>       inp:    array<vec4<u32>>;
@group(0) @binding(1) var<storage, read>       unused: array<vec4<u32>>;
@group(0) @binding(2) var<storage, read_write> outp:   array<vec4<u32>>;
@group(0) @binding(3) var<uniform>             params: vec4<u32>;

{{{ dec_unpack }}}

{{{ dec_pack }}}

fn load_be_packed(plane_base: u32, e: u32, N: u32) -> BigInt {
    // plane_base is in vec4 units; per plane: 2*N vec4 (PG=2).
    let base = plane_base + PG * e;
    let q0 = inp[base + 0u];
    let q1 = inp[base + 1u];
    var w: array<u32, 8>;
    w[0] = q0.x; w[1] = q0.y; w[2] = q0.z; w[3] = q0.w;
    w[4] = q1.x; w[5] = q1.y; w[6] = q1.z; w[7] = q1.w;
    return unpack256_to_limbs(w);
}

fn store_be_packed(plane_base: u32, e: u32, N: u32, val: ptr<function, BigInt>) {
    let w = pack_limbs_to_256(val);
    let base = plane_base + PG * e;
    outp[base + 0u] = vec4<u32>(w[0], w[1], w[2], w[3]);
    outp[base + 1u] = vec4<u32>(w[4], w[5], w[6], w[7]);
}

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let N = params.x;
    let T = params.y;
    let t = gid.x;
    if (t >= T) { return; }

    // Plane bases in vec4 units. Each plane spans PG*N vec4.
    let plane = PG * N;
    let ax_base = 0u * plane;
    let ay_base = 1u * plane;
    let px_base = 2u * plane;
    let py_base = 3u * plane;

    // Resident accumulator A.x stays in registers across the whole
    // chunk (drives the forward dx prefix chain). A.y is only needed in
    // the backward peel and is re-loaded there from the same SoA plane.
    var acc_x = load_be_packed(ax_base, t, N);

    // Forward pass: running prefix-product of the S dx values
    // dx_i = P_i.x - A_i.x. A_i is the prefix accumulator (resident).
    var pref: array<BigInt, {{ s }}>;
    var acc: BigInt = get_r();
    for (var i = 0u; i < S; i = i + 1u) {
        let e = t + i * T;
        var p_x = load_be_packed(px_base, e, N);
        var dx = fr_sub(&p_x, &acc_x);
        if (i == 0u) {
            acc = dx;
        } else {
            acc = montgomery_product(&acc, &dx);
        }
        pref[i] = acc;
        // Resident accumulator advances along the streamed chain:
        // A_0 is the seed, A_{i+1} := P_i. Points are independent
        // (P_i.x != A_i.x) so every dx is a well-defined nonzero
        // difference. inv_dx is deferred to the backward pass (ONE
        // fr_inv_by_a per chunk of S); A stays in registers throughout.
        acc_x = p_x;
    }

    var inv: BigInt = fr_inv_by_a(acc);

    // Backward peel + lean affine formula (dx recomputed free).
    for (var jj = 0u; jj < S; jj = jj + 1u) {
        let i = S - 1u - jj;
        let e = t + i * T;
        var p_x = load_be_packed(px_base, e, N);
        var p_y = load_be_packed(py_base, e, N);

        // A_i (left operand): A_0 is the seed, A_i = P_{i-1} for i>0
        // (matches the forward acc_x recurrence; points independent so
        // dx = P_i.x - A_i.x is always well-defined and nonzero).
        var a_x: BigInt;
        var a_y: BigInt;
        if (i == 0u) {
            a_x = load_be_packed(ax_base, t, N);
            a_y = load_be_packed(ay_base, t, N);
        } else {
            let ep = t + (i - 1u) * T;
            a_x = load_be_packed(px_base, ep, N);
            a_y = load_be_packed(py_base, ep, N);
        }

        var inv_dx: BigInt;
        if (i == 0u) {
            inv_dx = inv;
        } else {
            var pp = pref[i - 1u];
            inv_dx = montgomery_product(&inv, &pp);
        }

        var lambda = fr_sub(&p_y, &a_y);
        lambda = montgomery_product(&lambda, &inv_dx);
        var r_x = montgomery_product(&lambda, &lambda);
        r_x = fr_sub(&r_x, &a_x);
        r_x = fr_sub(&r_x, &p_x);
        var r_y = fr_sub(&a_x, &r_x);
        r_y = montgomery_product(&lambda, &r_y);
        r_y = fr_sub(&r_y, &a_y);

        store_be_packed(0u * plane, e, N, &r_x);
        store_be_packed(1u * plane, e, N, &r_y);

        if (i != 0u) {
            var dx_back = fr_sub(&p_x, &a_x);
            inv = montgomery_product(&inv, &dx_back);
        }
    }
}
`;

export const ba_scatter_pairs_bench = `{{> structs }}

// Scatter kernel for the bin-packed pair-tree MSM bucket-accumulate.
//
// For each (chunk t, slot k), reads R.x/R.y from the disjoint kernel's
// strided output (where it landed at flat index t + k * T after
// running with final_flag=1) and writes them to active_sums_new at
// the destination index given by scatter_plan[t * S + k].
//
// This is the per-bucket-placement pass that re-groups pair sums for
// the next level's bin-packing planner.
//
// scatter_plan layout: 1 u32 per (chunk, slot).
//   scatter_plan[t * S + k] = dst_idx  (active_sums_new index)
//
// disjoint_out layout: 2 planes (R.x, R.y), PG=2 vec4 per element,
// S * T elements per plane (matches the disjoint kernel's
// final-mode simple strided write).
//
// active_sums_new layout: 2 planes (P.x, P.y), PG=2 vec4 per element,
// M_new elements per plane (params.y).

const S: u32 = {{ s }}u;
const PG: u32 = 2u;

@group(0) @binding(0) var<storage, read>       scatter_plan:    array<u32>;
@group(0) @binding(1) var<storage, read>       disjoint_out:    array<vec4<u32>>;
@group(0) @binding(2) var<storage, read_write> active_sums_new: array<vec4<u32>>;
@group(0) @binding(3) var<uniform>             params:          vec4<u32>;

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let T = params.x;
    let M_new = params.y;
    let t = gid.x;
    if (t >= T) { return; }

    let out_N = S * T;
    let out_plane_x = 0u * PG * out_N;
    let out_plane_y = 1u * PG * out_N;

    let new_plane_x = 0u * PG * M_new;
    let new_plane_y = 1u * PG * M_new;

    for (var k: u32 = 0u; k < S; k = k + 1u) {
        let e = t + k * T;
        let dst_idx = scatter_plan[t * S + k];

        let src_x = out_plane_x + PG * e;
        let src_y = out_plane_y + PG * e;
        let dst_x = new_plane_x + PG * dst_idx;
        let dst_y = new_plane_y + PG * dst_idx;

        active_sums_new[dst_x + 0u] = disjoint_out[src_x + 0u];
        active_sums_new[dst_x + 1u] = disjoint_out[src_x + 1u];
        active_sums_new[dst_y + 0u] = disjoint_out[src_y + 0u];
        active_sums_new[dst_y + 1u] = disjoint_out[src_y + 1u];
    }

    {{{ recompile }}}
}
`;

export const ba_tail_reduce_bench = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> by_inverse_a_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

// Tail kernel for the bench-msm-tree pipeline: reduces a single
// tail-sized bucket (count < 2*S) to one sum per thread. Each thread
// reads its bucket's count points sequentially from the SoA-packed
// point pool and accumulates them via direct affine adds (one
// fr_inv_by_a per step).
//
// Pragmatic v1 — no batched inversion across threads. Each step pays
// one full fr_inv_by_a (~80 mont mul equivalents). For typical
// Poisson(lambda=16) MSM workloads, tail buckets carry a minority of
// total work (~10-30%); the contribution to overall bucket-accumulate
// ns/in-pt is small enough that this simple design is acceptable for
// a v1 complete-replacement kernel set. A workgroup-scan
// batched-inversion variant is a follow-on optimisation that would
// drop tail cost to ~25 ns/add (matching the main pair-tree).
//
// Bindings:
//   binding 0: csr_indices  — sorted point indices, 1-based (index 0 reserved).
//   binding 1: tail_plan    — three u32 per tail thread:
//                             [bucket_id, csr_start, count].
//   binding 2: point_pool   — SoA-packed pool (2 planes, PG=2 vec4/elem).
//   binding 3: bucket_sums  — SoA-packed output (2 planes, PG=2 vec4/bucket),
//                             one packed point per bucket. Pre-zeroed by host.
//   binding 4: params       — params.x=T (tail thread count),
//                             params.y=N (pool size),
//                             params.z=B (bucket_sums slot count).
//
// Bounded loop: the per-thread accumulate loop iterates up to compile-
// time TAIL_CAP = 2*S - 1, breaking early when i >= count. No
// data-dependent unbounded loops.

const TAIL_CAP: u32 = {{ tail_cap }}u;
const PG: u32 = 2u;

@group(0) @binding(0) var<storage, read>       csr_indices:  array<u32>;
@group(0) @binding(1) var<storage, read>       tail_plan:    array<u32>;
@group(0) @binding(2) var<storage, read>       point_pool:   array<vec4<u32>>;
@group(0) @binding(3) var<storage, read_write> bucket_sums:  array<vec4<u32>>;
@group(0) @binding(4) var<uniform>             params:       vec4<u32>;

fn load_pool(plane: u32, idx: u32, N: u32) -> BigInt {
    let plane_base = plane * PG * N;
    let base = plane_base + PG * idx;
    let q0 = point_pool[base + 0u];
    let q1 = point_pool[base + 1u];
    var w: array<u32, 8>;
    w[0] = q0.x; w[1] = q0.y; w[2] = q0.z; w[3] = q0.w;
    w[4] = q1.x; w[5] = q1.y; w[6] = q1.z; w[7] = q1.w;
    return unpack256_to_limbs(w);
}

fn store_bucket(plane: u32, b: u32, B: u32, val: ptr<function, BigInt>) {
    let plane_base = plane * PG * B;
    let base = plane_base + PG * b;
    let w = pack_limbs_to_256(val);
    bucket_sums[base + 0u] = vec4<u32>(w[0], w[1], w[2], w[3]);
    bucket_sums[base + 1u] = vec4<u32>(w[4], w[5], w[6], w[7]);
}

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let T = params.x;
    let N = params.y;
    let B = params.z;

    let t = gid.x;
    if (t >= T) { return; }

    let bucket_id = tail_plan[3u * t + 0u];
    let csr_start = tail_plan[3u * t + 1u];
    let count     = tail_plan[3u * t + 2u];

    if (count == 0u) { return; }

    var acc_x: BigInt = load_pool(0u, csr_indices[csr_start], N);
    var acc_y: BigInt = load_pool(1u, csr_indices[csr_start], N);

    for (var i: u32 = 1u; i < TAIL_CAP; i = i + 1u) {
        if (i >= count) { break; }
        let pt_idx = csr_indices[csr_start + i];
        var p_x: BigInt = load_pool(0u, pt_idx, N);
        var p_y: BigInt = load_pool(1u, pt_idx, N);
        var dx: BigInt = fr_sub(&p_x, &acc_x);
        var inv_dx: BigInt = fr_inv_by_a(dx);
        var dy: BigInt = fr_sub(&p_y, &acc_y);
        var lambda: BigInt = montgomery_product(&dy, &inv_dx);
        var lambda_sq: BigInt = montgomery_product(&lambda, &lambda);
        var r_x: BigInt = fr_sub(&lambda_sq, &acc_x);
        r_x = fr_sub(&r_x, &p_x);
        var r_y: BigInt = fr_sub(&acc_x, &r_x);
        r_y = montgomery_product(&lambda, &r_y);
        r_y = fr_sub(&r_y, &acc_y);
        acc_x = r_x;
        acc_y = r_y;
    }

    store_bucket(0u, bucket_id, B, &acc_x);
    store_bucket(1u, bucket_id, B, &acc_y);

    {{{ recompile }}}
}
`;

export const barrett = `const W_MASK = {{ w_mask }}u;
const SLACK = {{ slack }}u;

struct BigIntWide {
    limbs: array<u32, {{ num_words_mul_two }}>
}

fn get_mu() -> BigInt {
    var mu: BigInt;
{{{ mu_limbs }}}
    return mu;
}

fn get_p_wide() -> BigIntWide {
    var p: BigIntWide;
{{{ p_limbs }}}
    return p;
}

fn mul(a: ptr<function, BigInt>, b: ptr<function, BigInt>) -> BigIntWide {
    var res: BigIntWide;
    for (var i = 0u; i < NUM_WORDS; i = i + 1u) {
        for (var j = 0u; j < NUM_WORDS; j = j + 1u) {
            let c = (*a).limbs[i] * (*b).limbs[j];
            res.limbs[i+j] += c & W_MASK;
            res.limbs[i+j+1] += c >> WORD_SIZE;
        }   
    }

    // start from 0 and carry the extra over to the next index
    for (var i = 0u; i < 2 * NUM_WORDS - 1; i = i + 1u) {
        res.limbs[i+1] += res.limbs[i] >> WORD_SIZE;
        res.limbs[i] = res.limbs[i] & W_MASK;
    }
    return res;
}

fn sub_512(a: ptr<function, BigIntWide>, b: ptr<function, BigIntWide>, res: ptr<function, BigIntWide>) -> u32 {
    var borrow = 0u;
    for (var i = 0u; i < 2u * NUM_WORDS; i = i + 1u) {
        (*res).limbs[i] = (*a).limbs[i] - (*b).limbs[i] - borrow;
        if ((*a).limbs[i] < ((*b).limbs[i] + borrow)) {
            (*res).limbs[i] += W_MASK + 1u;
            borrow = 1u;
        } else {
            borrow = 0u;
        }
    }
    return borrow;
}

fn get_higher_with_slack(a: ptr<function, BigIntWide>) -> BigInt {
    var out: BigInt;
    for (var i = 0u; i < NUM_WORDS; i = i + 1u) {
        out.limbs[i] = (((*a).limbs[i + NUM_WORDS] << SLACK) + ((*a).limbs[i + NUM_WORDS - 1] >> (WORD_SIZE - SLACK))) & W_MASK;
    }
    return out;
}

fn field_mul(a: ptr<function, BigInt>, b: ptr<function, BigInt>) -> BigInt {
    var xy: BigIntWide = mul(a, b);
    var xy_hi: BigInt = get_higher_with_slack(&xy);
    var mu = get_mu();
    var l: BigIntWide = mul(&xy_hi, &mu);
    var l_hi: BigInt = get_higher_with_slack(&l);
    var p = get_p();
    var lp: BigIntWide = mul(&l_hi, &p);
    var r_wide: BigIntWide;
    sub_512(&xy, &lp, &r_wide);

    var r_wide_reduced: BigIntWide;
    var p_wide = get_p_wide();
    var underflow = sub_512(&r_wide, &p_wide, &r_wide_reduced);
    if (underflow == 0u) {
        r_wide = r_wide_reduced;
    }
    var r: BigInt;
    for (var i = 0u; i < NUM_WORDS; i = i + 1u) {
        r.limbs[i] = r_wide.limbs[i];
    }
    return fr_reduce(&r);
}
`;

export const batch_affine_apply = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}

// Batch-affine "apply" kernel — given N pairs (P_i, Q_i) and N
// pre-computed inverse deltas (1 / (Q_i.x - P_i.x)), compute the N
// affine sums P_i + Q_i = R_i in parallel and write them out.
//
// The N field inversions implicit in N independent affine adds have
// already been collapsed into a single inversion via the batch-inverse
// kernel (Montgomery's trick) — this kernel is the pure parallel
// arithmetic phase that consumes those pre-computed inverses.
//
// CALLER CONTRACT: every pair (P_i, Q_i) must have P_i.x != Q_i.x and
// neither operand is the identity. The batch-inverse on the deltas is
// undefined for delta == 0; degenerate pairs (P == Q for doubling,
// P == -Q for cancellation, or one operand at infinity) must be
// filtered by the scheduler before they enter the batch.
//
// All inputs / outputs are in Montgomery form. Affine add formulas:
//   λ        = (Q.y - P.y) * inv_delta
//   R.x      = λ^2 - P.x - Q.x
//   R.y      = λ * (P.x - R.x) - P.y

@group(0) @binding(0)
var<storage, read> pair_p_x: array<BigInt>;

@group(0) @binding(1)
var<storage, read> pair_p_y: array<BigInt>;

@group(0) @binding(2)
var<storage, read> pair_q_x: array<BigInt>;

@group(0) @binding(3)
var<storage, read> pair_q_y: array<BigInt>;

@group(0) @binding(4)
var<storage, read> inv_deltas: array<BigInt>;

@group(0) @binding(5)
var<storage, read_write> sum_x: array<BigInt>;

@group(0) @binding(6)
var<storage, read_write> sum_y: array<BigInt>;

@group(0) @binding(7)
var<uniform> params: vec4<u32>; // params[0] = N

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let i = global_id.x;
    let n = params[0];
    if (i >= n) {
        return;
    }

    var p_x: BigInt = pair_p_x[i];
    var p_y: BigInt = pair_p_y[i];
    var q_x: BigInt = pair_q_x[i];
    var q_y: BigInt = pair_q_y[i];
    var inv_d: BigInt = inv_deltas[i];

    // λ = (Q.y - P.y) * inv_delta
    var dy: BigInt = fr_sub(&q_y, &p_y);
    var lambda: BigInt = montgomery_product(&dy, &inv_d);

    // λ^2
    var lambda_sq: BigInt = montgomery_product(&lambda, &lambda);

    // R.x = λ^2 - P.x - Q.x
    var t1: BigInt = fr_sub(&lambda_sq, &p_x);
    var r_x: BigInt = fr_sub(&t1, &q_x);

    // R.y = λ * (P.x - R.x) - P.y
    var dx_back: BigInt = fr_sub(&p_x, &r_x);
    var ldx: BigInt = montgomery_product(&lambda, &dx_back);
    var r_y: BigInt = fr_sub(&ldx, &p_y);

    sum_x[i] = r_x;
    sum_y[i] = r_y;

    {{{ recompile }}}
}
`;

export const batch_affine_apply_scatter = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}

// Apply + scatter kernel for the batch-affine SMVP pipeline.
//
// Cross-subtask parallel dispatch: ONE dispatch per round covering ALL
// subtasks. Geometry: (apply_x_groups, 1, num_subtasks). Each subtask
// is a Z workgroup-row; one thread per (subtask, pair_slot) pair.
//
// Indirect-lookup design: instead of carrying P / Q coordinates in
// dedicated pair-pool buffers, we re-fetch them via the (bucket_global,
// q_cursor) pair stored by the schedule kernel:
//
//   pair_target_meta[i] = vec2<u32>(bucket_global, q_cursor)
//     P  = running_x/y[bucket_global]
//     Q  = new_point_x/y[val_idx[(bucket_global / num_columns) * input_size + q_cursor]]
//
// This re-derives the operands at minor extra cost but cuts the storage
// binding count to fit the WebGPU baseline of 8 storage buffers per
// stage. (Binding 8 is the uniform; uniforms are counted separately.)
//
// CALLER CONTRACT: every pair has P.x != Q.x (collision case is filtered
// by the scheduler — see batch_affine_schedule.template.wgsl).

@group(0) @binding(0)
var<storage, read> val_idx: array<u32>;
@group(0) @binding(1)
var<storage, read> new_point_x: array<BigInt>;
@group(0) @binding(2)
var<storage, read> new_point_y: array<BigInt>;

@group(0) @binding(3)
var<storage, read_write> running_x: array<BigInt>;
@group(0) @binding(4)
var<storage, read_write> running_y: array<BigInt>;

// pair_target_meta packs (bucket_global, q_cursor) per pair as TWO u32s.
//   pair_target_meta[2*i]     = bucket_global
//   pair_target_meta[2*i + 1] = q_cursor
// See batch_affine_schedule.template.wgsl for the rationale.
@group(0) @binding(5)
var<storage, read> pair_target_meta: array<u32>;
@group(0) @binding(6)
var<storage, read> inv_deltas: array<BigInt>;
// Per-subtask atomic counters. count_buf[subtask_idx] gives the number
// of active pairs the schedule kernel emitted for that subtask in this
// round. Bound as atomic-storage so we can atomicLoad it (cross-shader
// visibility of atomicAdd writes from the schedule kernel).
@group(0) @binding(7)
var<storage, read_write> count_buf: array<atomic<u32>>;

// params[0] = num_columns
// params[1] = input_size
// params[2] = unused
// params[3] = unused
@group(0) @binding(8)
var<uniform> params: vec4<u32>;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let i = global_id.x;
    let subtask_idx = global_id.z;
    let num_columns = params[0];
    let input_size = params[1];

    let n = atomicLoad(&count_buf[subtask_idx]);
    if (i >= n) {
        return;
    }

    let slot_global = subtask_idx * num_columns + i;
    let bucket_global = pair_target_meta[2u * slot_global];
    let q_cursor = pair_target_meta[2u * slot_global + 1u];

    let vi_offset = subtask_idx * input_size;
    let pt_idx = val_idx[vi_offset + q_cursor];
    var q_x: BigInt = new_point_x[pt_idx];
    var q_y: BigInt = new_point_y[pt_idx];

    var p_x: BigInt = running_x[bucket_global];
    var p_y: BigInt = running_y[bucket_global];

    var inv_d: BigInt = inv_deltas[slot_global];

    // λ = (Q.y - P.y) * inv_delta
    var dy: BigInt = fr_sub(&q_y, &p_y);
    var lambda: BigInt = montgomery_product(&dy, &inv_d);

    // R.x = λ^2 - P.x - Q.x
    var lambda_sq: BigInt = montgomery_product(&lambda, &lambda);
    var t1: BigInt = fr_sub(&lambda_sq, &p_x);
    var r_x: BigInt = fr_sub(&t1, &q_x);

    // R.y = λ * (P.x - R.x) - P.y
    var dx_back: BigInt = fr_sub(&p_x, &r_x);
    var ldx: BigInt = montgomery_product(&lambda, &dx_back);
    var r_y: BigInt = fr_sub(&ldx, &p_y);

    running_x[bucket_global] = r_x;
    running_y[bucket_global] = r_y;

    {{{ recompile }}}
}
`;

export const batch_affine_dispatch_args = `// Per-round indirect-dispatch argument writer for the batch-affine pipeline.
//
// Reads the per-subtask pair counters that the schedule kernel just wrote,
// computes max_count across subtasks, and writes three
// dispatchWorkgroupsIndirect arg triples into \`dispatch_args\`:
//
//   args[0..3] = schedule (X, 1, T)   -- schedule for the *NEXT* round
//                                         (this round already ran; we use
//                                         this round's max_count to predict
//                                         whether next round has any work)
//   args[3..6] = inverse  (T or 0, 1, 1) -- inverse for THIS round
//   args[6..9] = apply    (ceil(max/wg), 1, T) -- apply for THIS round
//
// Why predict NEXT round's schedule from THIS round's max_count:
//
//   The schedule kernel only adds a pair for buckets whose cursor is still
//   below row_end. Once a bucket's cursor reaches row_end it stays there
//   (schedule never decrements). So the moment a round adds zero pairs
//   (max_count == 0), it means every bucket on every subtask has run out
//   of points — and that state is monotonic forever after.
//
//   So we mark schedule's NEXT-round X dim to 0 the first time we see
//   max_count == 0. From then on schedule launches no workgroups; the
//   per-round cost collapses from a full sched_x_groups × T dispatch to
//   a near-zero indirect-X=0 pass. At N=2^18 with MAX_ROUNDS=64 and max
//   bucket depth ~36, this elides ~28 rounds × ~0.65 ms of schedule per
//   round = ~18 ms of late-round waste, plus shrinks the untimestamped
//   gap by the same amount.
//
//   Round 0's schedule_args are pre-seeded by the host before the round
//   loop (full size); from round 1 onward they're written by this kernel.
//
// All three pipelines (schedule / inverse / apply) read their arg triple
// via dispatchWorkgroupsIndirect from this same buffer at the offset
// indicated above.
//
// Single workgroup of 1 thread; runs once per round between schedule and
// inverse. Negligible cost (one tiny dispatch + a T-element scan over
// pair_counter), even at MAX_ROUNDS = 256.
//
// Also forwards each subtask's pair_counter value into round_count and
// zeroes pair_counter back in the same scan. Why this fold:
//
//   - inverse and apply read the per-subtask count; previously they
//     read pair_counter directly via atomicLoad.
//   - schedule's atomicAdd needs pair_counter to start each round at 0,
//     which used to be done by a per-round commandEncoder.clearBuffer
//     (256 invocations at N=2^20).
//   - Folding the read+forward+zero into this one-thread kernel
//     eliminates that clearBuffer entirely (256 → 0 at N=2^20). The
//     extra writes are negligible against the per-round work and
//     happen during a kernel that was already running.

@group(0) @binding(0)
var<storage, read_write> pair_counter: array<atomic<u32>>;

@group(0) @binding(1)
var<storage, read_write> round_count: array<atomic<u32>>;

@group(0) @binding(2)
var<storage, read_write> dispatch_args: array<u32>;

// WINDOWS_PER_BATCH — baked at render time. Controls the inverse-pass
// Z dispatch dim: num_batches = ceil(num_subtasks / WPB). See
// batch_inverse_parallel.template.wgsl for the merged-pool inverse.
const WPB: u32 = {{ windows_per_batch }}u;

// params[0] = num_subtasks
// params[1] = apply_workgroup_size
// params[2] = sched_x_groups   (= ceil(num_columns / schedule_workgroup_size))
// params[3] = num_sub_wgs_per_subtask  (= W; inverse dispatch X dim)
@group(0) @binding(3)
var<uniform> params: vec4<u32>;

@compute
@workgroup_size(1)
fn main() {
    let num_subtasks = params[0];
    let apply_wg_size = params[1];
    let sched_x_groups = params[2];
    let num_sub_wgs = params[3];
    let num_batches = (num_subtasks + WPB - 1u) / WPB;

    var max_count: u32 = 0u;
    for (var i: u32 = 0u; i < num_subtasks; i = i + 1u) {
        let n = atomicLoad(&pair_counter[i]);
        if (n > max_count) {
            max_count = n;
        }
        // Forward to round_count (read by THIS round's inverse + apply)
        // and zero pair_counter (used as atomicAdd target by NEXT round's
        // schedule). The forwarding step decouples the schedule and
        // inverse/apply readers — schedule writes pair_counter, inverse
        // and apply read round_count.
        atomicStore(&round_count[i], n);
        atomicStore(&pair_counter[i], 0u);
    }
    let any_work = max_count > 0u;

    // NEXT round's schedule: full sized when any work was added this
    // round, zero otherwise. Once zero, stays zero (cursors are monotone).
    let next_schedule_x = select(0u, sched_x_groups, any_work);
    dispatch_args[0] = next_schedule_x;
    dispatch_args[1] = 1u;
    dispatch_args[2] = num_subtasks;

    // THIS round's inverse: (W, 1, num_batches) workgroups — W sub-WGs
    // per (batch, sub_wg) splitting each batch's MERGED pair pool (of
    // size sum_{w} round_count[batch * WPB + w]) into W contiguous
    // slices, each independently inverted with its own fr_inv. Pooling
    // amortises one fr_inv across WPB subtasks. Z dim drops from T to
    // ceil(T/WPB) accordingly.
    let inverse_x = select(0u, num_sub_wgs, any_work);
    let inverse_z = select(0u, num_batches, any_work);
    dispatch_args[3] = inverse_x;
    dispatch_args[4] = 1u;
    dispatch_args[5] = inverse_z;

    // THIS round's apply: ceil(max_count / wg) X-groups, T Z-groups.
    // Naturally 0 when max_count == 0.
    let apply_x = (max_count + apply_wg_size - 1u) / apply_wg_size;
    dispatch_args[6] = apply_x;
    dispatch_args[7] = 1u;
    dispatch_args[8] = num_subtasks;
}
`;

export const batch_affine_finalize = `{{> structs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> bigint_funcs }}
{{> ec_funcs }}
{{> fr_pow_funcs }}

// Finalize kernel for the batch-affine SMVP pipeline.
//
// AFFINE FOLD VARIANT. Earlier versions of this kernel did the j=0 / j=1
// combine in Jacobian via add_points (function call) and the inlined
// add-2007-bl formula with Z3 hoisted up. Both paths produced
// bucket_y[i] == 0 (or bucket_z[i] == 0 in the function-call variant)
// on Dawn/Metal — Tint's register allocator was reusing BigInt slots
// across the long sequence of locals in the Jacobian formula, killing
// whichever output coordinate happened to be last.
//
// The OLD strategy of inlining + early Z3 worked for BPR stage_2 but
// broke when applied here. Repeated workarounds (storage-direct writes,
// outer X3_out/Y3_out/Z3_out, restructured branching) all produced the
// same all-zero Y output. CPU pipeline simulator confirmed the algorithm
// is correct, so the issue is purely Dawn/Tint register-allocation
// fragility specific to this call site.
//
// This rewrite SIDESTEPS the Jacobian formula entirely by performing
// the j=0/j=1 add in pure affine — the two operands are already affine
// (Z=R is the implicit Montgomery-1 packaging; geometrically (X, Y)).
// Each thread does one fr_inv (~500 montgomery_products) — pricey, but
// uses only the same primitives (fr_sub, montgomery_product) that
// batch_affine_apply uses successfully. ~16 M mont_prod total at
// h=32768; profiled cost will be ~100-300 ms on M-series silicon.
// Optimisation note: a future pass can replace the per-thread fr_inv
// with a batch_inverse over all delta_x's, cutting cost to ~3*N + 1
// montgomery_products. But correctness first.
//
// Outputs Jacobian-with-Z=R so downstream BPR sees the same layout the
// legacy SMVP produces.
//
//   - Two row-indices per thread (j = 0 and j = 1).
//   - For row_idx > h: the recovered bucket_idx is positive (row_idx - h).
//   - For row_idx < h: bucket_idx = h - row_idx, and the sum is negated.
//   - For row_idx == h: bucket_idx = 0 — bucket has no contribution; skip.
//   - For row_idx == 0 (only j=0 when id%h == 0): bucket_idx = h.

@group(0) @binding(0)
var<storage, read> running_x: array<BigInt>;
@group(0) @binding(1)
var<storage, read> running_y: array<BigInt>;
@group(0) @binding(2)
var<storage, read> bucket_active: array<u32>;

@group(0) @binding(3)
var<storage, read_write> bucket_x: array<BigInt>;
@group(0) @binding(4)
var<storage, read_write> bucket_y: array<BigInt>;
@group(0) @binding(5)
var<storage, read_write> bucket_z: array<BigInt>;

@group(0) @binding(6)
var<uniform> params: vec4<u32>;
// params[0] = num_y_workgroups
// params[1] = num_z_workgroups
// params[2] = subtask_offset
// params[3] = workspace_stride

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

// Negate Y in field: returns p - y (assumes 0 <= y < p, which fr_sub
// outputs guarantee).
fn neg_y(running_idx: u32) -> BigInt {
    var p_mod = get_p();
    var y = running_y[running_idx];
    var ny: BigInt;
    let _b = bigint_sub(&p_mod, &y, &ny);
    return ny;
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let num_y_workgroups = params[0];
    let num_z_workgroups = params[1];
    let subtask_offset = params[2];
    let workspace_stride = params[3];

    let gidx = global_id.x;
    let gidy = global_id.y;
    var gidz = global_id.z;
    let id = (gidx * num_y_workgroups + gidy) * num_z_workgroups + gidz;

    let num_columns = {{ num_columns }}u;
    let h = {{ half_num_columns }}u;

    let subtask_idx = id / h;
    let bi = id + subtask_offset * h;
    let workspace_offset = (subtask_idx + subtask_offset) * workspace_stride;

    // ---- Resolve j = 0 side as affine (X1, Y1) + active flag ----
    var p1_x: BigInt;
    var p1_y: BigInt;
    var p1_active: bool = false;
    {
        var row_idx = (id % h) + h;
        if (id % h == 0u) {
            row_idx = 0u;
        }

        var bucket_idx: u32 = 0u;
        var negate: bool = false;
        if (h > row_idx) {
            bucket_idx = h - row_idx;
            negate = true;
        } else {
            bucket_idx = row_idx - h;
        }

        if (bucket_idx > 0u) {
            let workspace_idx = workspace_offset + row_idx;
            if (bucket_active[workspace_idx] != 0u) {
                p1_x = running_x[workspace_idx];
                if (negate) {
                    p1_y = neg_y(workspace_idx);
                } else {
                    p1_y = running_y[workspace_idx];
                }
                p1_active = true;
            }
        }
    }

    // ---- Resolve j = 1 side as affine (X2, Y2) + active flag ----
    var p2_x: BigInt;
    var p2_y: BigInt;
    var p2_active: bool = false;
    {
        let row_idx = h - (id % h);
        var bucket_idx: u32 = 0u;
        var negate: bool = false;
        if (h > row_idx) {
            bucket_idx = h - row_idx;
            negate = true;
        } else {
            bucket_idx = row_idx - h;
        }

        if (bucket_idx > 0u) {
            let workspace_idx = workspace_offset + row_idx;
            if (bucket_active[workspace_idx] != 0u) {
                p2_x = running_x[workspace_idx];
                if (negate) {
                    p2_y = neg_y(workspace_idx);
                } else {
                    p2_y = running_y[workspace_idx];
                }
                p2_active = true;
            }
        }
    }

    // ---- Combine and write directly to storage ----
    //
    // Cases:
    //   - !p1_active && !p2_active: bucket is identity (X=0, Y=R, Z=0).
    //   - p1_active xor p2_active: result = (Xa, Ya, R) for the active side.
    //   - both active: pure affine add.
    //
    // Storage default-zero-init: when we write nothing, the slot stays 0.
    // For the identity case we still set y = R explicitly so downstream
    // is_zero(z) checks see (X=0, Y=R, Z=0) which all Jacobian primitives
    // treat as point-at-infinity.

    if (!p1_active && !p2_active) {
        var zero: BigInt;
        bucket_x[bi] = zero;
        bucket_y[bi] = get_r();
        bucket_z[bi] = zero;
        return;
    }

    if (!p2_active) {
        bucket_x[bi] = p1_x;
        bucket_y[bi] = p1_y;
        bucket_z[bi] = get_r();
        return;
    }

    if (!p1_active) {
        bucket_x[bi] = p2_x;
        bucket_y[bi] = p2_y;
        bucket_z[bi] = get_r();
        return;
    }

    // Both active. Affine add.
    //   delta = X2 - X1
    //   λ     = (Y2 - Y1) * delta^{-1}
    //   R.x   = λ² - X1 - X2
    //   R.y   = λ * (X1 - R.x) - Y1
    //
    // SRS-backed bases — collision (delta == 0) is statistically
    // impossible. A future hardening pass can detect and route through
    // double_point if needed.
    var delta = fr_sub(&p2_x, &p1_x);
    var inv_d = fr_inv(delta);

    var dy = fr_sub(&p2_y, &p1_y);
    var lambda = montgomery_product(&dy, &inv_d);

    var lambda_sq = montgomery_product(&lambda, &lambda);
    var t1 = fr_sub(&lambda_sq, &p1_x);
    var r_x = fr_sub(&t1, &p2_x);

    var dx_back = fr_sub(&p1_x, &r_x);
    var ldx = montgomery_product(&lambda, &dx_back);
    var r_y = fr_sub(&ldx, &p1_y);

    bucket_x[bi] = r_x;
    bucket_y[bi] = r_y;
    bucket_z[bi] = get_r();

    {{{ recompile }}}
}
`;

