export const horner_reduce_bn254 = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> ec_funcs }}

// GPU-side replacement for the CPU Horner reduction at the tail of the
// MSM. Two entry points dispatched in sequence:
//
//   subtask_reduce — T workgroups of TPB threads each. Workgroup k
//     reduces g_points[k*b_wg .. (k+1)*b_wg - 1] into one Jacobian
//     point and writes it to subtask_sums[k]. Each thread does a
//     serial chunk of (b_wg / TPB) adds, then cooperative tree
//     reduction in workgroup memory.
//
//   horner_chain — 1 workgroup, 1 thread. Reads subtask_sums[0..T-1]
//     and walks the Horner chain, writing the final result to
//     result_x/y/z[0].
//
// Why two kernels:
// - Inter-workgroup sync requires a dispatch boundary in WebGPU; we
//   need all subtask_sums written before the Horner chain can start.
// - The previous single-workgroup design ran all T subtask reductions
//   on a single SM (the workgroup's threads get packed into one Metal
//   SIMD group), which serialised the per-subtask 256-add chains.
//   Spreading subtasks across T workgroups parallelises across SMs.
//
// Compute budget (BN254, T=16, b_wg=256, chunk=16):
//   subtask_reduce: 16 workgroups × (256/32 + log2(32)) ≈ 13 adds/thread
//                   wall = 13 * (11M+5S) ≈ 200 muls × ~50 ns ≈ 10 µs
//   horner_chain:   16 doublings × 15 + 15 adds ≈ 17 mont-mul-equiv per
//                   chunk × 15 chunks ≈ 250 muls ≈ 12 µs
//   Total: ~25 µs wall time vs the previous ~45 ms (single-SM packed).

const TPB: u32 = 32u;
const B_WG_SIZE: u32 = {{ b_workgroup_size }}u;
const CHUNK_SIZE: u32 = {{ chunk_size }}u;
const T: u32 = {{ num_subtasks }}u;

{{#packed}}
@group(0) @binding(0)
var<storage, read> g_points_x: array<vec4<u32>>;
@group(0) @binding(1)
var<storage, read> g_points_y: array<vec4<u32>>;
@group(0) @binding(2)
var<storage, read> g_points_z: array<vec4<u32>>;
{{/packed}}
{{^packed}}
@group(0) @binding(0)
var<storage, read> g_points_x: array<BigInt>;
@group(0) @binding(1)
var<storage, read> g_points_y: array<BigInt>;
@group(0) @binding(2)
var<storage, read> g_points_z: array<BigInt>;
{{/packed}}

// Combined scratch + result buffer (T+1 BigInts per coordinate):
//   index 0..T-1 — per-subtask partial sum (written by subtask_reduce,
//                  read by horner_chain).
//   index T     — final Horner result (written by horner_chain, read by CPU).
//
// Packing all three coordinates into one buffer pair (sums_x, sums_y, sums_z)
// instead of six separate buffers keeps us within the 8-storage-buffers-
// per-stage WebGPU baseline (current shader: 3 read-only g_points +
// 3 read-write packed = 6 storage bindings).
{{#packed}}
@group(0) @binding(3)
var<storage, read_write> sums_x: array<vec4<u32>>;
@group(0) @binding(4)
var<storage, read_write> sums_y: array<vec4<u32>>;
@group(0) @binding(5)
var<storage, read_write> sums_z: array<vec4<u32>>;
{{/packed}}
{{^packed}}
@group(0) @binding(3)
var<storage, read_write> sums_x: array<BigInt>;
@group(0) @binding(4)
var<storage, read_write> sums_y: array<BigInt>;
@group(0) @binding(5)
var<storage, read_write> sums_z: array<BigInt>;
{{/packed}}

{{#packed}}
{{{ dec_unpack }}}

{{{ dec_pack }}}

fn load_packed_ro(base_elem: u32, src: ptr<storage, array<vec4<u32>>, read>) -> BigInt {
    var w: array<u32, 8>;
    let q0 = (*src)[2u * base_elem];
    let q1 = (*src)[2u * base_elem + 1u];
    w[0] = q0.x; w[1] = q0.y; w[2] = q0.z; w[3] = q0.w;
    w[4] = q1.x; w[5] = q1.y; w[6] = q1.z; w[7] = q1.w;
    return unpack256_to_limbs(w);
}

fn load_packed_rw(base_elem: u32, src: ptr<storage, array<vec4<u32>>, read_write>) -> BigInt {
    var w: array<u32, 8>;
    let q0 = (*src)[2u * base_elem];
    let q1 = (*src)[2u * base_elem + 1u];
    w[0] = q0.x; w[1] = q0.y; w[2] = q0.z; w[3] = q0.w;
    w[4] = q1.x; w[5] = q1.y; w[6] = q1.z; w[7] = q1.w;
    return unpack256_to_limbs(w);
}

fn store_packed_rw(base_elem: u32, dst: ptr<storage, array<vec4<u32>>, read_write>, val: ptr<function, BigInt>) {
    let w = pack_limbs_to_256(val);
    (*dst)[2u * base_elem] = vec4<u32>(w[0], w[1], w[2], w[3]);
    (*dst)[2u * base_elem + 1u] = vec4<u32>(w[4], w[5], w[6], w[7]);
}
{{/packed}}

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

fn get_paf() -> Point {
    var p: Point;
    p.y = get_r();
    return p;
}

// Workgroup memory for tree reduction. TPB partial sums × sizeof(Point).
// At TPB=32: 32 * 240 = 7680 bytes — half of the 16 KB default cap.
var<workgroup> wg_partials: array<Point, TPB>;

@compute
@workgroup_size(TPB)
fn subtask_reduce(
    @builtin(local_invocation_id) lid: vec3<u32>,
    @builtin(workgroup_id) wid: vec3<u32>,
) {
    let tid = lid.x;
    let subtask_idx = wid.x;
    let base = subtask_idx * B_WG_SIZE;

    // Per-thread serial chunk: each thread sums its slice of (b_wg / TPB)
    // points. With b_wg=256 and TPB=32, that's 8 adds per thread.
    let chunk = B_WG_SIZE / TPB;
    let chunk_start = tid * chunk;
    var acc: Point = get_paf();
    for (var i: u32 = 0u; i < chunk; i = i + 1u) {
        let idx = base + chunk_start + i;
        var p: Point;
{{#packed}}
        p.x = load_packed_ro(idx, &g_points_x);
        p.y = load_packed_ro(idx, &g_points_y);
        p.z = load_packed_ro(idx, &g_points_z);
{{/packed}}
{{^packed}}
        p.x = g_points_x[idx];
        p.y = g_points_y[idx];
        p.z = g_points_z[idx];
{{/packed}}
        acc = add_points(acc, p);
    }
    wg_partials[tid] = acc;

    workgroupBarrier();

    // Tree reduction: log2(TPB) passes of halve-and-add.
    var stride: u32 = TPB / 2u;
    while (stride > 0u) {
        if (tid < stride) {
            let other = wg_partials[tid + stride];
            wg_partials[tid] = add_points(wg_partials[tid], other);
        }
        workgroupBarrier();
        stride = stride / 2u;
    }

    // Thread 0 writes this subtask's sum at slot subtask_idx.
    if (tid == 0u) {
        let s = wg_partials[0];
{{#packed}}
        var sx = s.x; var sy = s.y; var sz = s.z;
        store_packed_rw(subtask_idx, &sums_x, &sx);
        store_packed_rw(subtask_idx, &sums_y, &sy);
        store_packed_rw(subtask_idx, &sums_z, &sz);
{{/packed}}
{{^packed}}
        sums_x[subtask_idx] = s.x;
        sums_y[subtask_idx] = s.y;
        sums_z[subtask_idx] = s.z;
{{/packed}}
    }

    {{{ recompile }}}
}

// Final-result slot index (T-th element of sums_*). Caller reads back
// these three positions to recover the MSM result.
const RESULT_SLOT: u32 = {{ num_subtasks }}u;

// Parallel Horner chain. The serial Horner walk
//   result = s[T-1]; for j=T-2..0: result = result*2^cs + s[j]
// expands to:
//   result = Σ_{j=0..T-1} subtask_sums[j] · 2^(j · CHUNK_SIZE)
// (s[T-1] is multiplied by 2^cs once per loop iter, s[T-2] T-2 times,
// ..., s[0] zero times — coefficient of s[j] is 2^(j·cs).)
//
// Each thread tid takes subtask_sums[tid] and applies tid · CHUNK_SIZE
// doublings. A workgroup tree-reduce then sums the T scaled points.
//
// Wall time vs the previous workgroup_size=1 design: each thread runs
// at most (T-1)·CHUNK_SIZE doublings (≤ 240 for production), but all T
// threads execute in lockstep within one Metal SIMD group, replacing
// 240 single-threaded doublings on idle hardware. Roughly 10× speedup.
//
// Workgroup memory: reuses wg_partials[0..T-1]. T ≤ TPB by construction.
@compute
@workgroup_size({{ num_subtasks }})
fn horner_chain(@builtin(local_invocation_id) lid: vec3<u32>) {
    let tid = lid.x;

    // Load subtask_sums[tid] and apply tid·CHUNK_SIZE doublings.
    var p: Point;
{{#packed}}
    p.x = load_packed_rw(tid, &sums_x);
    p.y = load_packed_rw(tid, &sums_y);
    p.z = load_packed_rw(tid, &sums_z);
{{/packed}}
{{^packed}}
    p.x = sums_x[tid];
    p.y = sums_y[tid];
    p.z = sums_z[tid];
{{/packed}}
    let n_doublings = tid * CHUNK_SIZE;
    for (var i: u32 = 0u; i < n_doublings; i = i + 1u) {
        p = double_point(p);
    }
    wg_partials[tid] = p;

    workgroupBarrier();

    // Tree reduce: log2(T) passes of halve-and-add.
    var stride: u32 = T / 2u;
    while (stride > 0u) {
        if (tid < stride) {
            wg_partials[tid] = add_points(wg_partials[tid], wg_partials[tid + stride]);
        }
        workgroupBarrier();
        stride = stride / 2u;
    }

    // Thread 0 writes the final result.
    if (tid == 0u) {
        let r = wg_partials[0];
{{#packed}}
        var rx = r.x; var ry = r.y; var rz = r.z;
        store_packed_rw(RESULT_SLOT, &sums_x, &rx);
        store_packed_rw(RESULT_SLOT, &sums_y, &ry);
        store_packed_rw(RESULT_SLOT, &sums_z, &rz);
{{/packed}}
{{^packed}}
        sums_x[RESULT_SLOT] = r.x;
        sums_y[RESULT_SLOT] = r.y;
        sums_z[RESULT_SLOT] = r.z;
{{/packed}}
    }

    {{{ recompile }}}
}
`;

export const smvp_bn254 = `{{> structs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> bigint_funcs }}
{{> ec_funcs }}

// Input buffers
@group(0) @binding(0)
var<storage, read> row_ptr: array<u32>;
@group(0) @binding(1)
var<storage, read> val_idx: array<u32>;
@group(0) @binding(2)
var<storage, read> new_point_x: array<BigInt>;
@group(0) @binding(3)
var<storage, read> new_point_y: array<BigInt>;

// Output buffers
@group(0) @binding(4)
var<storage, read_write> bucket_x: array<BigInt>;
@group(0) @binding(5)
var<storage, read_write> bucket_y: array<BigInt>;
@group(0) @binding(6)
var<storage, read_write> bucket_z: array<BigInt>;

// Params buffer
@group(0) @binding(7)
var<uniform> params: vec4<u32>;

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

fn get_paf() -> Point {
    var result: Point;
    result.y = get_r();
    return result;
}

// This double-and-add code is adapted from the ZPrize test harness:
// https://github.com/demox-labs/webgpu-msm/blob/main/src/reference/webgpu/wgsl/Curve.ts#L78
fn double_and_add(point: Point, scalar: u32) -> Point {
    // Set result to the point at infinity
    var result: Point = get_paf();

    var s = scalar;
    var temp = point;

    while (s != 0u) {
        if ((s & 1u) == 1u) {
            result = add_points(result, temp);
        }
        temp = double_point(temp);
        s = s >> 1u;
    }
    return result;
}

// Point negation only involves multiplying the Y coordinate by -1 in
// the field
fn negate_point(point: Point) -> Point {
    var p = get_p();
    var y = point.y;
    var neg_y: BigInt;
    bigint_sub(&p, &y, &neg_y);
    return Point(point.x, neg_y, point.z);
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let input_size = params[0];
    let num_y_workgroups = params[1];
    let num_z_workgroups = params[2];
    let subtask_offset = params[3];

    let gidx = global_id.x;
    let gidy = global_id.y;
    var gidz = global_id.z;
    let id = (gidx * num_y_workgroups + gidy) * num_z_workgroups + gidz;

    let num_columns = {{ num_columns }}u;
    let l = num_columns;
    let h = {{ half_num_columns }}u;

    // Define custom subtask_idx
    let subtask_idx = (id / h);

    var inf = get_paf();

    let rp_offset = (subtask_idx + subtask_offset) * (num_columns + 1u);

    // As we use the signed bucket index technique, each thread handles two
    // buckets.
    for (var j = 0u; j < 2u; j ++) {
        var row_idx = (id % h) + h;
        if (j == 1u) {
            row_idx = h - (id % h);
        }

        if (j == 0u && id % h == 0u) {
            row_idx = 0u;
        }

        // Skip the chunk=0 row (row h). The (j=1, id%h=0) thread would
        // otherwise iterate through every scalar whose signed chunk is 0
        // — at the top subtask of BN254 Fr this is nearly all of them
        // (random Fr < 2^254 means chunk_17's top bits are zero, and most
        // scalars don't propagate a carry that far) — and write nothing
        // because bucket_idx = 0 is the "no contribution" sentinel. One
        // thread spinning through n/2 mixed-adds is enough to trip
        // Chrome's GPU-process watchdog at n >= 2^17, dropping the device
        // and leaving bucket buffers at their initial (zero) state. Bail
        // before the inner loop runs.
        if (j == 1u && id % h == 0u) {
            continue;
        }

        let row_begin = row_ptr[rp_offset + row_idx];
        let row_end = row_ptr[rp_offset + row_idx + 1u];
        var sum = inf;

        // Add up all the points in the bucket.
        //
        // Jacobian-mixed-add hot path: every \`pt\` loaded here has Z = R
        // (Montgomery 1) by construction, so we call \`add_points_mixed\`
        // which uses the Z2=1 formula (7M+4S) instead of the general
        // Jacobian add (11M+5S). \`pt.z\` is ignored by add_points_mixed —
        // we still set it so the Point struct is fully initialised.
        //
        // Use the NO-COLLISION variant: SRS bases are linearly independent
        // random points in G1, so the running bucket sum can never
        // affinely equal a fresh SRS point being added (would require a
        // discrete-log accident). Saves 2 × bigint_eq per call. The
        // identity short-circuit at the top of the function is kept
        // (genuine: first iter has sum.z == 0).
        for (var k = row_begin; k < row_end; k ++) {
            let idx = val_idx[(subtask_idx + subtask_offset) * input_size + k];

            var x = new_point_x[idx];
            var y = new_point_y[idx];
            var z = get_r();
            let pt = Point(x, y, z);

            sum = add_points_mixed_no_collision(sum, pt);
        }

        // Negate the point if the recovered bucket index is negative.
        // Since we've added half_num_columns to each scalar chunk in
        // convert_point_coords_and_decompose_scalars.template.wgsl, we know if
        // the original bucket index is negative if it is less than
        // half_num_columns.
        var bucket_idx = 0u;
        if (h > row_idx) {
            bucket_idx = h - row_idx;
            sum = negate_point(sum);
        } else {
            bucket_idx = row_idx - h;
        }

        let bi = id + subtask_offset * h;

        if (bucket_idx > 0u) {
            // Store the result in buckets[thread_id]. Each thread must use
            // a unique storage location (thread_id) to prevent race
            // conditions.
            if (j == 1) {
                // Since the point has been set, add to it.
                let bucket = Point(
                    bucket_x[bi],
                    bucket_y[bi],
                    bucket_z[bi]
                );
                sum = add_points(bucket, sum);
            }

            // Set the point. Since no point has been set when j == 0, we can just
            // overwrite the data.
            bucket_x[bi] = sum.x;
            bucket_y[bi] = sum.y;
            bucket_z[bi] = sum.z;
        }
    }

    {{{ recompile }}}
}
`;

export const smvp_tree_entry_bucket_id = `// Derives entry_bucket_id[i] for every schedule entry, given the
// per-subtask CSR layout used by the existing batch-affine pipeline:
//
//   row_ptr layout: (num_subtasks * (num_columns + 1)) entries.
//     row_ptr[subtask_idx * (num_columns + 1) + bucket_local] = row_begin
//   val_idx layout: (num_subtasks * input_size) entries; entries within
//     one subtask are bucket-sorted by bucket_local.
//
// For entry index \`i\` (in val_idx):
//   subtask_idx = i / input_size
//   offset      = i % input_size
//   bucket_local = largest B in [0, num_columns] with row_ptr[subtask_idx
//                  * (num_columns + 1) + B] <= offset
//   bucket_global = subtask_idx * num_columns + bucket_local
//
// One thread per entry. Dispatch (ceil(total_entries / TPB), 1, 1).

const TPB: u32 = {{ tpb }}u;

@group(0) @binding(0)
var<storage, read> row_ptr: array<u32>;
@group(0) @binding(1)
var<storage, read_write> entry_bucket_id: array<u32>;

struct Params {
    num_columns: u32,
    input_size: u32,
    num_subtasks: u32,
    pad: u32,
}
@group(0) @binding(2)
var<uniform> params: Params;

@compute
@workgroup_size({{ tpb }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    let total_entries = params.input_size * params.num_subtasks;
    if (i >= total_entries) { return; }

    let subtask_idx = i / params.input_size;
    let offset = i % params.input_size;
    let rp_base = subtask_idx * (params.num_columns + 1u);

    var lo: u32 = 0u;
    var hi: u32 = params.num_columns;
    for (var step: u32 = 0u; step < 32u; step = step + 1u) {
        if (lo >= hi) { break; }
        let mid = (lo + hi + 1u) / 2u;
        if (row_ptr[rp_base + mid] <= offset) {
            lo = mid;
        } else {
            hi = mid - 1u;
        }
    }
    entry_bucket_id[i] = subtask_idx * params.num_columns + lo;

    {{{ recompile }}}
}
`;

export const smvp_tree_phase1 = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> by_inverse_a_funcs }}

// Phase 1 of the tree-reduce SMVP (v3 — fully parallel preamble).
//
// One workgroup per slice. PER-WG WORK IS NOW EVENLY DISTRIBUTED:
//   - Preamble (parallel pair detection):
//       Each of TPB threads processes PER_THREAD_ENTRIES =
//       MAX_SLICE_ENTRIES / TPB entries from the slice's bucket-sorted
//       stream. Each entry's \`pos_in_run\` (its position within its
//       contiguous same-bucket run, with the run reset at slice_lo)
//       is recovered by a TPB-wide max-scan of per-thread "last break
//       position". An entry "emits" iff (pos_in_run & 1u) == 0u — and
//       is a PAIR iff its successor in the slice has the same bucket
//       id (else UNPAIRED). Per-thread emit / pair counts feed two
//       TPB-wide prefix-sums to assign raw_slot and pair_rank ranges
//       without any serial state machine.
//   - Phase A: per-thread inclusive-prefix product of delta_x over
//       PER_THREAD_PAIRS PAIRs in PAIR-rank order. ONE static loop —
//       no scan over MAX_PAIRS. ONLY reads point_x — point_y is not
//       touched in Phase A (saves ~50% of point-data bandwidth on
//       large WG inputs).
//   - Phase B: TPB-wide Hillis-Steele scan of per-thread block_total.
//   - Phase C: thread-0 fr_inv_by_a on the global product.
//   - Phase D: per-thread back-walk of the same chunk in descending
//       PAIR-rank order, computing affine adds. inv_dx for PAIR rank R
//       uses the precomputed previous-PAIR raw_slot (O(1) lookup,
//       no backward scan).
//
// Workgroup memory at MAX_PAIRS=1024, TPB=64:
//   pair_idx_a/b/prev_raw/rank_to_raw: 4 × 4 KB = 16 KB
//   thread_max_break/emit_prefix/pair_prefix: 3 × 256 B = 768 B
//   wg_fwd, wg_bwd:                  2 × TPB × 80 = 10.24 KB
//   wg_inv_total + counters:         ~120 B
//   total:                           ~27.1 KB (under M2's 32 KB cap).
//
// Static loop bounds:
//   Preamble Step 1 (load buckets + local break-max): PER_THREAD_ENTRIES
//   Preamble Step 2 (TPB max-scan):                  log2(TPB)
//   Preamble Step 3 (emit/pair flags):               PER_THREAD_ENTRIES
//   Preamble Step 4 (TPB prefix-sum):                log2(TPB)
//   Preamble Step 5 (write pair_idx*/rank_to_raw):   PER_THREAD_ENTRIES
//   Preamble Step 6 (write prev_raw_for_pair):       PER_THREAD_ENTRIES
//   Phase A:                                          PER_THREAD_PAIRS
//   Phase B:                                          log2(TPB)
//   Phase D:                                          PER_THREAD_PAIRS
//   UNPAIRED write-out:                              MAX_PAIRS / TPB

const TPB: u32 = {{ tpb }}u;
const MAX_SLICE_ENTRIES: u32 = {{ max_slice_entries }}u;
const MAX_PAIRS: u32 = {{ max_pairs }}u;
const PER_THREAD_ENTRIES: u32 = {{ per_thread_entries }}u;
const PER_THREAD_PAIRS: u32 = {{ per_thread_pairs }}u;
const UNPAIRED_SENTINEL: u32 = 0xffffffffu;
const SCHEDULE_SIGN_BIT: u32 = 0x80000000u;
const SCHEDULE_IDX_MASK: u32 = 0x7fffffffu;

@group(0) @binding(0)
var<storage, read> schedule: array<u32>;            // (sign << 31) | scalar_idx

@group(0) @binding(1)
var<storage, read> entry_bucket_id: array<u32>;     // bucket id per entry

@group(0) @binding(2)
var<storage, read> point_x: array<BigInt>;

@group(0) @binding(3)
var<storage, read> point_y: array<BigInt>;

@group(0) @binding(4)
var<storage, read> slice_bounds: array<u32>;        // length num_wgs+1

@group(0) @binding(5)
var<storage, read> wg_output_offset: array<u32>;    // length num_wgs+1

@group(0) @binding(6)
var<storage, read_write> prefix_scratch: array<BigInt>;  // size num_wgs * MAX_PAIRS

@group(0) @binding(7)
var<storage, read_write> output_bucket_id: array<u32>;

@group(0) @binding(8)
var<storage, read_write> output_x: array<BigInt>;

@group(0) @binding(9)
var<storage, read_write> output_y: array<BigInt>;

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}
// \`get_p()\` is provided by the \`montgomery_product_funcs\` partial.

var<workgroup> pair_idx_a: array<u32, {{ max_pairs }}>;
var<workgroup> pair_idx_b: array<u32, {{ max_pairs }}>;
var<workgroup> prev_raw_for_pair: array<u32, {{ max_pairs }}>;
var<workgroup> rank_to_raw: array<u32, {{ max_pairs }}>;

var<workgroup> thread_max_break: array<u32, {{ tpb }}>;
var<workgroup> thread_emit_prefix: array<u32, {{ tpb }}>;
var<workgroup> thread_pair_prefix: array<u32, {{ tpb }}>;

var<workgroup> pair_count_wg: u32;
var<workgroup> num_pairs_real_wg: u32;

var<workgroup> wg_fwd: array<BigInt, {{ tpb }}>;
var<workgroup> wg_bwd: array<BigInt, {{ tpb }}>;
var<workgroup> wg_inv_total: BigInt;

fn load_point_x_only(entry_idx: u32) -> BigInt {
    let raw = schedule[entry_idx];
    let scalar_idx = raw & SCHEDULE_IDX_MASK;
    return point_x[scalar_idx];
}

fn load_point(entry_idx: u32, out_x: ptr<function, BigInt>, out_y: ptr<function, BigInt>) {
    let raw = schedule[entry_idx];
    let scalar_idx = raw & SCHEDULE_IDX_MASK;
    *out_x = point_x[scalar_idx];
    var py: BigInt = point_y[scalar_idx];
    if ((raw & SCHEDULE_SIGN_BIT) != 0u) {
        var zero: BigInt;
        py = fr_sub(&zero, &py);
    }
    *out_y = py;
}

@compute
@workgroup_size({{ tpb }})
fn main(
    @builtin(local_invocation_id) lid: vec3<u32>,
    @builtin(workgroup_id) wid: vec3<u32>,
) {
    let tid = lid.x;
    let wg_id = wid.x;
    let slice_lo = slice_bounds[wg_id];
    let slice_hi = slice_bounds[wg_id + 1u];
    let out_base = wg_output_offset[wg_id];

    let chunk_lo = slice_lo + tid * PER_THREAD_ENTRIES;
    var chunk_hi_v: u32 = chunk_lo + PER_THREAD_ENTRIES;
    if (chunk_hi_v > slice_hi) { chunk_hi_v = slice_hi; }
    if (chunk_lo > slice_hi) { chunk_hi_v = chunk_lo; }
    let chunk_hi = chunk_hi_v;

    // === Preamble Step 1: per-thread bucket load + local "last break pos" ===
    // For each entry e in [chunk_lo, chunk_hi):
    //   is_break iff (e == slice_lo) OR (bucket[e] != bucket[e-1])
    //   local_break_pos[off] = max{e' <= e : is_break(e')}
    // local_buckets[] caches bucket_id for re-use in Steps 3 and 5.
    var local_buckets: array<u32, {{ per_thread_entries }}>;
    var local_break_pos: array<u32, {{ per_thread_entries }}>;
    var prev_bucket: u32 = UNPAIRED_SENTINEL;
    if (chunk_lo > slice_lo && chunk_lo < slice_hi) {
        prev_bucket = entry_bucket_id[chunk_lo - 1u];
    }
    var max_break: u32 = 0u;
    for (var off: u32 = 0u; off < PER_THREAD_ENTRIES; off = off + 1u) {
        let e = chunk_lo + off;
        if (e < chunk_hi) {
            let b = entry_bucket_id[e];
            local_buckets[off] = b;
            var is_break: bool;
            if (e == slice_lo) {
                is_break = true;
            } else if (off == 0u) {
                is_break = b != prev_bucket;
            } else {
                is_break = b != local_buckets[off - 1u];
            }
            if (is_break) {
                max_break = e;
            }
        } else {
            local_buckets[off] = UNPAIRED_SENTINEL;
        }
        local_break_pos[off] = max_break;
    }

    // === Preamble Step 2: TPB-wide inclusive max-scan of max_break ===
    thread_max_break[tid] = max_break;
    workgroupBarrier();
    for (var stride: u32 = 1u; stride < TPB; stride = stride * 2u) {
        var v: u32 = thread_max_break[tid];
        if (tid >= stride) {
            let lhs = thread_max_break[tid - stride];
            if (lhs > v) { v = lhs; }
        }
        workgroupBarrier();
        thread_max_break[tid] = v;
        workgroupBarrier();
    }
    // Exclusive prefix-max for this thread.
    var prev_thread_max: u32 = 0u;
    if (tid > 0u) {
        prev_thread_max = thread_max_break[tid - 1u];
    }
    for (var off: u32 = 0u; off < PER_THREAD_ENTRIES; off = off + 1u) {
        if (prev_thread_max > local_break_pos[off]) {
            local_break_pos[off] = prev_thread_max;
        }
    }
    // Now: pos_in_run(e) = e - local_break_pos[off] for e in this chunk.

    // === Preamble Step 3: emit / pair flags ===
    var next_chunk_bucket: u32 = UNPAIRED_SENTINEL;
    if (chunk_hi < slice_hi) {
        next_chunk_bucket = entry_bucket_id[chunk_hi];
    }
    var local_emit: u32 = 0u;
    var local_pair: u32 = 0u;
    var local_emit_mask: u32 = 0u;
    var local_pair_mask: u32 = 0u;
    for (var off: u32 = 0u; off < PER_THREAD_ENTRIES; off = off + 1u) {
        let e = chunk_lo + off;
        if (e >= chunk_hi) { continue; }
        let p = e - local_break_pos[off];
        if ((p & 1u) != 0u) { continue; }
        local_emit = local_emit + 1u;
        local_emit_mask = local_emit_mask | (1u << off);
        var next_b: u32 = UNPAIRED_SENTINEL;
        if (off + 1u < PER_THREAD_ENTRIES) {
            if (e + 1u < chunk_hi) {
                next_b = local_buckets[off + 1u];
            }
        } else {
            if (e + 1u < slice_hi) {
                next_b = next_chunk_bucket;
            }
        }
        if (next_b == local_buckets[off]) {
            local_pair = local_pair + 1u;
            local_pair_mask = local_pair_mask | (1u << off);
        }
    }

    // === Preamble Step 4: TPB-wide prefix-sum of emit + pair counts ===
    thread_emit_prefix[tid] = local_emit;
    thread_pair_prefix[tid] = local_pair;
    workgroupBarrier();
    for (var stride: u32 = 1u; stride < TPB; stride = stride * 2u) {
        var ev: u32 = thread_emit_prefix[tid];
        var pv: u32 = thread_pair_prefix[tid];
        if (tid >= stride) {
            ev = ev + thread_emit_prefix[tid - stride];
            pv = pv + thread_pair_prefix[tid - stride];
        }
        workgroupBarrier();
        thread_emit_prefix[tid] = ev;
        thread_pair_prefix[tid] = pv;
        workgroupBarrier();
    }
    var raw_base: u32 = 0u;
    var pair_base: u32 = 0u;
    if (tid > 0u) {
        raw_base = thread_emit_prefix[tid - 1u];
        pair_base = thread_pair_prefix[tid - 1u];
    }
    if (tid == 0u) {
        pair_count_wg = thread_emit_prefix[TPB - 1u];
        num_pairs_real_wg = thread_pair_prefix[TPB - 1u];
    }
    workgroupBarrier();

    // === Preamble Step 5: write pair_idx_a/b, rank_to_raw, output_bucket_id ===
    var raw_w: u32 = raw_base;
    var pair_w: u32 = pair_base;
    for (var off: u32 = 0u; off < PER_THREAD_ENTRIES; off = off + 1u) {
        if ((local_emit_mask & (1u << off)) == 0u) { continue; }
        let e = chunk_lo + off;
        let raw = raw_w;
        raw_w = raw_w + 1u;
        pair_idx_a[raw] = e;
        if ((local_pair_mask & (1u << off)) != 0u) {
            pair_idx_b[raw] = e + 1u;
            let pair_rank = pair_w;
            pair_w = pair_w + 1u;
            rank_to_raw[pair_rank] = raw;
        } else {
            pair_idx_b[raw] = UNPAIRED_SENTINEL;
        }
        output_bucket_id[out_base + raw] = local_buckets[off];
    }
    workgroupBarrier();

    // === Preamble Step 6: write prev_raw_for_pair using rank_to_raw ===
    var raw_r: u32 = raw_base;
    var pair_r: u32 = pair_base;
    for (var off: u32 = 0u; off < PER_THREAD_ENTRIES; off = off + 1u) {
        if ((local_emit_mask & (1u << off)) == 0u) { continue; }
        let raw = raw_r;
        raw_r = raw_r + 1u;
        if ((local_pair_mask & (1u << off)) != 0u) {
            let pair_rank = pair_r;
            pair_r = pair_r + 1u;
            if (pair_rank == 0u) {
                prev_raw_for_pair[raw] = UNPAIRED_SENTINEL;
            } else {
                prev_raw_for_pair[raw] = rank_to_raw[pair_rank - 1u];
            }
        }
    }
    workgroupBarrier();

    let total_outputs = pair_count_wg;
    let total_pairs = num_pairs_real_wg;

    // Phase A: per-thread prefix product over PER_THREAD_PAIRS PAIRs
    // assigned to this thread's contiguous PAIR-rank chunk. Only x is
    // read; y is not needed for dx = Q.x - P.x.
    let chunk_start_rank = tid * PER_THREAD_PAIRS;
    var block_total: BigInt = get_r();
    for (var t: u32 = 0u; t < PER_THREAD_PAIRS; t = t + 1u) {
        let rank = chunk_start_rank + t;
        if (rank >= total_pairs) { break; }
        let raw = rank_to_raw[rank];
        let idx_a = pair_idx_a[raw];
        let idx_b = pair_idx_b[raw];
        var p_x: BigInt = load_point_x_only(idx_a);
        var q_x: BigInt = load_point_x_only(idx_b);
        var dx: BigInt = fr_sub(&q_x, &p_x);
        if (t == 0u) {
            block_total = dx;
        } else {
            block_total = montgomery_product(&block_total, &dx);
        }
        prefix_scratch[wg_id * MAX_PAIRS + raw] = block_total;
    }

    wg_fwd[tid] = block_total;
    wg_bwd[tid] = block_total;
    workgroupBarrier();

    // Phase B: Hillis-Steele forward + backward scans.
    for (var stride: u32 = 1u; stride < TPB; stride = stride * 2u) {
        var fwd_x: BigInt = wg_fwd[tid];
        if (tid >= stride) {
            var lhs: BigInt = wg_fwd[tid - stride];
            fwd_x = montgomery_product(&lhs, &fwd_x);
        }
        var bwd_x: BigInt = wg_bwd[tid];
        if (tid + stride < TPB) {
            var rhs: BigInt = wg_bwd[tid + stride];
            bwd_x = montgomery_product(&bwd_x, &rhs);
        }
        workgroupBarrier();
        wg_fwd[tid] = fwd_x;
        wg_bwd[tid] = bwd_x;
        workgroupBarrier();
    }

    // Phase C: thread-0 global inverse.
    if (tid == 0u) {
        if (total_pairs > 0u) {
            var global_total: BigInt = wg_fwd[TPB - 1u];
            wg_inv_total = fr_inv_by_a(global_total);
        }
    }
    workgroupBarrier();

    var block_excl_prefix: BigInt = get_r();
    if (tid > 0u) {
        block_excl_prefix = wg_fwd[tid - 1u];
    }
    var block_excl_suffix: BigInt = get_r();
    if (tid + 1u < TPB) {
        block_excl_suffix = wg_bwd[tid + 1u];
    }
    var inv_acc: BigInt;
    if (total_pairs == 0u) {
        inv_acc = get_r();
    } else {
        var inv_global: BigInt = wg_inv_total;
        inv_acc = montgomery_product(&inv_global, &block_excl_prefix);
        inv_acc = montgomery_product(&inv_acc, &block_excl_suffix);
    }

    // Phase D: back-walk this thread's PAIR-rank chunk in descending
    // fwd-rank order. PER_THREAD_PAIRS iterations, no scan.
    var thread_pair_count_local: u32 = 0u;
    if (chunk_start_rank < total_pairs) {
        let avail = total_pairs - chunk_start_rank;
        if (avail >= PER_THREAD_PAIRS) {
            thread_pair_count_local = PER_THREAD_PAIRS;
        } else {
            thread_pair_count_local = avail;
        }
    }
    var inv_acc_local: BigInt = inv_acc;
    for (var off: u32 = 0u; off < PER_THREAD_PAIRS; off = off + 1u) {
        if (off >= thread_pair_count_local) { break; }
        let rank = chunk_start_rank + (thread_pair_count_local - 1u - off);
        let raw = rank_to_raw[rank];
        let idx_a = pair_idx_a[raw];
        let idx_b = pair_idx_b[raw];
        var p_x: BigInt; var p_y: BigInt;
        load_point(idx_a, &p_x, &p_y);
        var q_x: BigInt; var q_y: BigInt;
        load_point(idx_b, &q_x, &q_y);

        var inv_dx: BigInt;
        if (rank == chunk_start_rank) {
            inv_dx = inv_acc_local;
        } else {
            let prev_raw = prev_raw_for_pair[raw];
            var prev_prefix: BigInt = prefix_scratch[wg_id * MAX_PAIRS + prev_raw];
            inv_dx = montgomery_product(&inv_acc_local, &prev_prefix);
        }

        var dy: BigInt = fr_sub(&q_y, &p_y);
        var slope: BigInt = montgomery_product(&dy, &inv_dx);
        var slope_sq: BigInt = montgomery_product(&slope, &slope);
        var t1: BigInt = fr_sub(&slope_sq, &p_x);
        var r_x: BigInt = fr_sub(&t1, &q_x);
        var dx_back: BigInt = fr_sub(&p_x, &r_x);
        var ldx: BigInt = montgomery_product(&slope, &dx_back);
        var r_y: BigInt = fr_sub(&ldx, &p_y);

        output_x[out_base + raw] = r_x;
        output_y[out_base + raw] = r_y;

        if (rank > chunk_start_rank) {
            var dx_k: BigInt = fr_sub(&q_x, &p_x);
            inv_acc_local = montgomery_product(&inv_acc_local, &dx_k);
        }
    }

    // Write-out UNPAIRED slots cooperatively round-robin.
    for (var off: u32 = 0u; off < (MAX_PAIRS + TPB - 1u) / TPB; off = off + 1u) {
        let i = tid + off * TPB;
        if (i >= total_outputs) { break; }
        let idx_b = pair_idx_b[i];
        if (idx_b != UNPAIRED_SENTINEL) { continue; }
        let idx_a = pair_idx_a[i];
        var p_x: BigInt; var p_y: BigInt;
        load_point(idx_a, &p_x, &p_y);
        output_x[out_base + i] = p_x;
        output_y[out_base + i] = p_y;
    }

    {{{ recompile }}}
}
`;

